  "started_at" timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  "completed_at" timestamp with time zone,
  "created_at" timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);
CREATE TABLE public."trade_ins" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "trade_in_code" text NOT NULL,
  "customer_id" bigint,
  "order_id" bigint,
  "brand" text NOT NULL,
  "model" text NOT NULL,
  "serial" text,
  "cpu" text,
  "gpu" text,
  "ram" text,
  "ssd" text,
  "status" text NOT NULL,
  "estimated_value_vnd" numeric(18,2),
  "agreed_value_vnd" numeric(18,2),
  "reported_condition" text,
  "notes" text,
  "received_at" timestamp with time zone,
  "inventory_laptop_id" bigint,
  "idempotency_key" text NOT NULL,
  "created_by" text NOT NULL,
  "created_at" timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  "updated_at" timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);
CREATE TABLE public."user_profiles" (
  "id" uuid NOT NULL,
  "name" text,
  "role" text DEFAULT 'SALES'::text NOT NULL,
  "is_active" boolean DEFAULT true,
  "created_at" timestamp with time zone DEFAULT timezone('utc'::text, now()),
  "updated_at" timestamp with time zone DEFAULT timezone('utc'::text, now())
);
CREATE TABLE public."warranty_cases" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" bigint,
  "laptop_id" bigint,
  "reported_issue" text,
  "status" text,
  "received_date" date,
  "resolved_date" date,
  "repair_cost" numeric DEFAULT 0,
  "parts_replaced" text,
  "diagnosis" text,
  "resolution" text,
  "resolution_note" text,
  "notes" text,
  "customer_info" text,
  "handled_by" text,
  "created_at" timestamp with time zone DEFAULT timezone('utc'::text, now()),
  "updated_at" timestamp with time zone DEFAULT timezone('utc'::text, now())
);

