-- INDEXES
CREATE INDEX account_reconciliations_account_idx ON public.account_reconciliations USING btree (account_id, reconciled_at DESC);
CREATE INDEX account_transactions_account_time_idx ON public.account_transactions USING btree (account_id, occurred_at DESC, id);
CREATE UNIQUE INDEX account_transactions_source_unique ON public.account_transactions USING btree (reference_type, reference_id, transaction_type);
CREATE INDEX activity_logs_entity_created_at_idx ON public.activity_logs USING btree (entity_type, entity_id, created_at DESC);
CREATE INDEX cod_receivables_status_due_idx ON public.cod_receivables USING btree (status, expected_settlement_at);
CREATE INDEX cod_settlements_receivable_idx ON public.cod_settlements USING btree (cod_receivable_id, settled_at, id);
CREATE UNIQUE INDEX commissions_source_unique ON public.commissions USING btree (order_id, beneficiary_type, COALESCE((beneficiary_user_id)::text, beneficiary_name), commission_type) WHERE (status <> 'CANCELLED'::text);
CREATE UNIQUE INDEX customers_phone_unique_ci_idx ON public.customers USING btree (lower(btrim(phone))) WHERE ((phone IS NOT NULL) AND (btrim(phone) <> ''::text));
CREATE INDEX financial_records_date_idx ON public.financial_records USING btree (occurred_on DESC, id DESC);
CREATE INDEX financial_records_order_idx ON public.financial_records USING btree (order_id, occurred_on DESC);
CREATE INDEX invoices_customer_idx ON public.invoices USING btree (customer_id);
CREATE INDEX invoices_laptop_idx ON public.invoices USING btree (laptop_id);
CREATE INDEX laptop_cost_components_laptop_idx ON public.laptop_cost_components USING btree (laptop_id, occurred_at, id);
CREATE UNIQUE INDEX laptop_cost_components_source_unique ON public.laptop_cost_components USING btree (laptop_id, source_type, source_id, cost_type) WHERE ((source_id IS NOT NULL) AND (voided_at IS NULL));
CREATE UNIQUE INDEX laptop_cost_components_trade_in_source_unique ON public.laptop_cost_components USING btree (source_id) WHERE ((source_type = 'TRADE_IN'::text) AND (cost_type = 'TRADE_IN_ACQUISITION'::text) AND (voided_at IS NULL));
CREATE INDEX idx_laptops_month_key ON public.laptops USING btree (month_key);
CREATE INDEX laptops_active_status_import_date_idx ON public.laptops USING btree (is_active, status, import_date DESC);
CREATE INDEX laptops_purchase_batch_idx ON public.laptops USING btree (purchase_batch_id, id);
CREATE UNIQUE INDEX laptops_serial_unique_ci_idx ON public.laptops USING btree (lower(btrim((serial)::text))) WHERE ((serial IS NOT NULL) AND (btrim((serial)::text) <> ''::text));
CREATE UNIQUE INDEX laptops_serial_unique_idx ON public.laptops USING btree (lower(btrim((serial)::text))) WHERE ((serial IS NOT NULL) AND (btrim((serial)::text) <> ''::text));
CREATE UNIQUE INDEX laptops_sku_unique ON public.laptops USING btree (sku);
CREATE INDEX laptops_status_received_idx ON public.laptops USING btree (status, received_at DESC, id DESC);
CREATE INDEX laptops_tracking_code_cn_idx ON public.laptops USING btree (lower(tracking_code_cn)) WHERE (btrim(tracking_code_cn) <> ''::text);
CREATE UNIQUE INDEX laptops_tracking_code_cn_unique_idx ON public.laptops USING btree (lower(btrim(tracking_code_cn))) WHERE (btrim(tracking_code_cn) <> ''::text AND is_active IS TRUE);
CREATE INDEX idx_orders_month_key ON public.orders USING btree (month_key);
CREATE INDEX orders_laptop_active_idx ON public.orders USING btree (laptop_id, is_active, order_status, payment_status);
CREATE INDEX orders_requested_laptop_idx ON public.orders USING btree (requested_laptop_id, is_active, order_status, payment_status);
CREATE UNIQUE INDEX payments_idempotency_unique ON public.payments USING btree (idempotency_key) WHERE (idempotency_key IS NOT NULL);
CREATE INDEX payments_order_date_idx ON public.payments USING btree (order_id, payment_date DESC, id DESC);
CREATE UNIQUE INDEX purchase_batches_idempotency_unique ON public.purchase_batches USING btree (idempotency_key) WHERE (idempotency_key IS NOT NULL);
CREATE INDEX purchase_batches_supplier_idx ON public.purchase_batches USING btree (supplier_id, purchase_date DESC);
CREATE UNIQUE INDEX qc_inspections_completion_idempotency_unique ON public.qc_inspections USING btree (completion_idempotency_key) WHERE (completion_idempotency_key IS NOT NULL);
CREATE INDEX qc_inspections_laptop_history_idx ON public.qc_inspections USING btree (laptop_id, started_at DESC);
CREATE UNIQUE INDEX qc_inspections_one_active_per_laptop ON public.qc_inspections USING btree (laptop_id) WHERE (status = 'IN_PROGRESS'::text);
CREATE UNIQUE INDEX repair_jobs_one_active_per_laptop ON public.repair_jobs USING btree (laptop_id) WHERE (status <> ALL (ARRAY['COMPLETED'::text, 'CANCELLED'::text]));
CREATE INDEX repair_jobs_status_idx ON public.repair_jobs USING btree (status, priority, created_at DESC);
CREATE UNIQUE INDEX reservations_one_active_laptop ON public.reservations USING btree (laptop_id) WHERE (status = 'ACTIVE'::text);
CREATE INDEX reservations_status_expiry_idx ON public.reservations USING btree (status, expires_at);
CREATE INDEX stock_movements_laptop_created_at_idx ON public.stock_movements USING btree (laptop_id, created_at DESC);
CREATE INDEX supplier_payments_batch_idx ON public.supplier_payments USING btree (purchase_batch_id, payment_date, id);
CREATE INDEX supplier_refunds_return_idx ON public.supplier_refunds USING btree (supplier_return_id, received_at, id);
CREATE INDEX supplier_return_events_return_idx ON public.supplier_return_events USING btree (supplier_return_id, created_at, id);
CREATE UNIQUE INDEX supplier_return_items_one_active_laptop ON public.supplier_return_items USING btree (laptop_id) WHERE (status <> ALL (ARRAY['REFUNDED'::text, 'REPLACED'::text, 'REJECTED'::text, 'CANCELLED'::text]));
CREATE UNIQUE INDEX supplier_return_items_replacement_laptop_unique ON public.supplier_return_items USING btree (replacement_laptop_id) WHERE (replacement_laptop_id IS NOT NULL);
CREATE INDEX supplier_return_items_return_idx ON public.supplier_return_items USING btree (supplier_return_id, status, id);
CREATE INDEX supplier_returns_supplier_status_idx ON public.supplier_returns USING btree (supplier_id, status, created_at DESC);
CREATE INDEX supplier_returns_tracking_idx ON public.supplier_returns USING btree (lower(return_tracking_number)) WHERE (btrim(return_tracking_number) <> ''::text);
CREATE UNIQUE INDEX trade_in_one_open_inspection ON public.trade_in_inspections USING btree (trade_in_id) WHERE (status = 'IN_PROGRESS'::text);
CREATE UNIQUE INDEX trade_ins_inventory_source_unique ON public.trade_ins USING btree (inventory_laptop_id) WHERE (inventory_laptop_id IS NOT NULL);
CREATE UNIQUE INDEX trade_ins_serial_active_unique ON public.trade_ins USING btree (lower(serial)) WHERE ((serial IS NOT NULL) AND (status <> ALL (ARRAY['REJECTED'::text, 'CANCELLED'::text])));
CREATE INDEX warranty_cases_laptop_created_at_idx ON public.warranty_cases USING btree (laptop_id, created_at DESC);
CREATE UNIQUE INDEX warranty_cases_one_open_per_laptop_idx ON public.warranty_cases USING btree (laptop_id) WHERE (status = ANY (ARRAY['received'::text, 'checking'::text, 'wait_parts'::text, 'repairing'::text]));

-- VIEWS
CREATE VIEW public."cash_account_balances" AS
 SELECT a.id,
    a.code,
    a.name,
    a.account_type,
    a.currency,
    a.opening_balance,
    a.opening_balance_at,
    a.is_active,
    a.created_by,
    a.created_at,
    a.updated_at,
    COALESCE(t.inflow, 0::numeric)::numeric(20,2) AS inflow,
    COALESCE(t.outflow, 0::numeric)::numeric(20,2) AS outflow,
    (a.opening_balance + COALESCE(t.inflow, 0::numeric) - COALESCE(t.outflow, 0::numeric))::numeric(20,2) AS recorded_balance,
    t.last_transaction_at,
    r.last_reconciled_at,
    r.last_difference
   FROM cash_accounts a
     LEFT JOIN ( SELECT x.account_id,
            sum(x.amount) FILTER (WHERE x.direction = 'IN'::text) AS inflow,
            sum(x.amount) FILTER (WHERE x.direction = 'OUT'::text) AS outflow,
            max(x.occurred_at) AS last_transaction_at
           FROM account_transactions x
             JOIN cash_accounts ca ON ca.id = x.account_id
          WHERE x.occurred_at >= ca.opening_balance_at
          GROUP BY x.account_id) t ON t.account_id = a.id
     LEFT JOIN LATERAL ( SELECT account_reconciliations.reconciled_at AS last_reconciled_at,
            account_reconciliations.difference AS last_difference
           FROM account_reconciliations
          WHERE account_reconciliations.account_id = a.id
          ORDER BY account_reconciliations.reconciled_at DESC
         LIMIT 1) r ON true;;
CREATE VIEW public."cod_receivable_summaries" AS
 SELECT c.id,
    c.order_id,
    c.carrier,
    c.tracking_number,
    c.expected_cod_amount_vnd,
    c.status,
    c.shipped_at,
    c.delivered_at,
    c.expected_settlement_at,
    c.settled_at,
    c.notes,
    c.idempotency_key,
    c.created_by,
    c.created_at,
    c.updated_at,
    COALESCE(s.settled_vnd, 0::numeric)::numeric(20,2) AS settled_vnd,
    GREATEST(c.expected_cod_amount_vnd - COALESCE(s.settled_vnd, 0::numeric), 0::numeric)::numeric(20,2) AS outstanding_vnd,
    o.customer_id,
    o.sale_price,
    o.amount_paid,
    o.debt_amount
   FROM cod_receivables c
     JOIN orders o ON o.id = c.order_id
     LEFT JOIN ( SELECT cod_settlements.cod_receivable_id,
            sum(cod_settlements.amount_vnd) AS settled_vnd
           FROM cod_settlements
          GROUP BY cod_settlements.cod_receivable_id) s ON s.cod_receivable_id = c.id;;
CREATE VIEW public."customer_receivable_summaries" AS
 SELECT o.id AS order_id,
    o.customer_id,
    c.name AS customer_name,
    c.phone AS customer_phone,
    o.sale_price,
    o.amount_paid,
    o.debt_amount,
    o.payment_due_at,
    o.created_date,
    o.sale_online AS salesperson,
    ( SELECT max(p.payment_date) AS max
           FROM payments p
          WHERE p.order_id = o.id) AS last_payment_date,
        CASE
            WHEN o.payment_due_at IS NULL THEN 'NO_DUE_DATE'::text
            WHEN o.payment_due_at >= now() THEN 'NOT_DUE'::text
            WHEN (now() - o.payment_due_at) <= '7 days'::interval THEN 'OVERDUE_1_7'::text
            WHEN (now() - o.payment_due_at) <= '30 days'::interval THEN 'OVERDUE_8_30'::text
            WHEN (now() - o.payment_due_at) <= '60 days'::interval THEN 'OVERDUE_31_60'::text
            ELSE 'OVERDUE_60_PLUS'::text
        END AS aging_bucket
   FROM orders o
     LEFT JOIN customers c ON c.id = o.customer_id
  WHERE o.is_active AND o.debt_amount > 0::numeric AND (o.order_status::text <> ALL (ARRAY['cancelled'::character varying, 'returned'::character varying]::text[])) AND o.payment_status::text <> 'refunded'::text;;
CREATE VIEW public."order_sales_operations_summary" AS
 SELECT o.id AS order_id,
    o.sale_price * 1000000::numeric AS sale_revenue_vnd,
    o.trade_in_credit_vnd,
    o.debt_amount * 1000000::numeric AS customer_outstanding_vnd,
    o.gross_profit_snapshot_vnd,
    o.net_contribution_snapshot_vnd,
    COALESCE(sum(c.amount_vnd) FILTER (WHERE c.status = ANY (ARRAY['APPROVED'::text, 'PAID'::text])), 0::numeric) AS commission_cost_vnd,
    o.net_contribution_snapshot_vnd - COALESCE(sum(c.amount_vnd) FILTER (WHERE c.status = ANY (ARRAY['APPROVED'::text, 'PAID'::text])), 0::numeric) AS net_contribution_after_commission_vnd
   FROM orders o
     LEFT JOIN commissions c ON c.order_id = o.id
  GROUP BY o.id;;
CREATE VIEW public."purchase_batch_summaries" AS
 SELECT b.id,
    b.batch_code,
    b.supplier_id,
    b.purchase_date,
    b.notes,
    b.created_by,
    b.created_at,
    b.updated_at,
    b.idempotency_key,
    s.code AS supplier_code,
    s.name AS supplier_name,
    COALESCE(x.laptop_count, 0::bigint) AS item_count,
    COALESCE(x.received_count, 0::bigint) AS received_count,
    COALESCE(x.pending_count, 0::bigint) AS pending_count,
    COALESCE(x.ignored_count, 0::bigint) AS ignored_count,
    COALESCE(x.purchase_total_rmb, 0::numeric)::numeric(14,2) AS subtotal_rmb,
    COALESCE(x.purchase_total_rmb, 0::numeric)::numeric(14,2) AS purchase_total_rmb,
    COALESCE(x.shipping_total_rmb, 0::numeric)::numeric(14,2) AS shipping_total_rmb,
    COALESCE(x.purchase_total_rmb, 0::numeric)::numeric(14,2) AS total_rmb,
    COALESCE(p.paid_rmb, 0::numeric)::numeric(14,2) AS paid_rmb,
    GREATEST(COALESCE(x.purchase_total_rmb, 0::numeric) - COALESCE(p.paid_rmb, 0::numeric), 0::numeric)::numeric(14,2) AS debt_rmb,
        CASE
            WHEN COALESCE(x.pending_count, 0::bigint) = 0 THEN 'RECEIVED'::text
            WHEN COALESCE(x.received_count, 0::bigint) > 0 THEN 'PARTIALLY_RECEIVED'::text
            ELSE 'IN_TRANSIT'::text
        END AS status
   FROM purchase_batches b
     JOIN suppliers s ON s.id = b.supplier_id
     LEFT JOIN ( SELECT laptops.purchase_batch_id,
            count(*) AS laptop_count,
            count(*) FILTER (WHERE laptops.received_at IS NOT NULL) AS received_count,
            count(*) FILTER (WHERE laptops.status::text = 'in_transit'::text) AS pending_count,
            count(*) FILTER (WHERE laptops.status::text = 'ignored'::text) AS ignored_count,
            sum(laptops.purchase_price_rmb) FILTER (WHERE laptops.status::text <> 'ignored'::text) AS purchase_total_rmb,
            sum(laptops.shipping_rmb) FILTER (WHERE laptops.status::text <> 'ignored'::text) AS shipping_total_rmb
           FROM laptops
          WHERE laptops.purchase_batch_id IS NOT NULL
          GROUP BY laptops.purchase_batch_id) x ON x.purchase_batch_id = b.id
     LEFT JOIN ( SELECT supplier_payments.purchase_batch_id,
            sum(supplier_payments.amount_rmb) AS paid_rmb
           FROM supplier_payments
          GROUP BY supplier_payments.purchase_batch_id) p ON p.purchase_batch_id = b.id;;
CREATE VIEW public."laptop_landed_costs" AS
 WITH component_sums AS (
         SELECT laptop_cost_components.laptop_id,
            sum(laptop_cost_components.amount_vnd) FILTER (WHERE laptop_cost_components.cost_type = 'TRADE_IN_ACQUISITION'::text) AS trade_in_cost_vnd,
            sum(laptop_cost_components.amount_vnd) FILTER (WHERE laptop_cost_components.cost_type = 'VN_SHIPPING'::text) AS vn_shipping_vnd,
            sum(laptop_cost_components.amount_vnd) FILTER (WHERE laptop_cost_components.cost_type = 'REPAIR'::text) AS repair_cost_vnd,
            sum(laptop_cost_components.amount_vnd) FILTER (WHERE laptop_cost_components.cost_type = ANY (ARRAY['RAM_UPGRADE'::text, 'SSD_UPGRADE'::text])) AS upgrade_cost_vnd,
            sum(laptop_cost_components.amount_vnd) FILTER (WHERE laptop_cost_components.cost_type = 'ACCESSORY'::text) AS accessory_cost_vnd,
            sum(laptop_cost_components.amount_vnd) FILTER (WHERE laptop_cost_components.cost_type = ANY (ARRAY['CLEANING'::text, 'OTHER'::text, 'PAYMENT_FEE'::text])) AS other_cost_vnd,
            sum(laptop_cost_components.amount_vnd) FILTER (WHERE laptop_cost_components.cost_type = 'REFUND_CREDIT'::text) AS refund_credit_vnd
           FROM laptop_cost_components
          WHERE laptop_cost_components.voided_at IS NULL
          GROUP BY laptop_cost_components.laptop_id
        ), calculated AS (
         SELECT l.id,
            l.serial,
            l.name,
            l.category,
            l.import_date,
            l.warehouse_date,
            l.location,
            l.charger_status,
            l.status,
            l.price_rmb,
            l.shipping_rmb,
            l.exchange_rate,
            l.import_price_vnd,
            l.wholesale_price_vnd,
            l.retail_price_vnd,
            l.tracking_code,
            l.customer_note,
            l.battery_health,
            l.warranty_supplier,
            l.screen_status,
            l.camera_mic_status,
            l.mainboard_status,
            l.condition_note,
            l.seller,
            l.is_active,
            l.parts_history,
            l.month_key,
            l.created_at,
            l.updated_at,
            l.sku,
            l.available_for_sale_at,
            l.source_type,
            l.source_reference_id,
            l.purchase_batch_id,
            l.tracking_code_cn,
            l.purchase_price_rmb,
            l.purchase_exchange_rate,
            l.received_at,
            l.sold_at,
            l.ignored_at,
            l.ignored_by,
            l.ignore_reason,
            l.created_by,
                CASE
                    WHEN l.source_type = 'TRADE_IN'::text THEN COALESCE(c.trade_in_cost_vnd, 0::numeric)
                    WHEN l.purchase_exchange_rate IS NOT NULL THEN round(l.purchase_price_rmb * l.purchase_exchange_rate, 2)
                    ELSE 0::numeric
                END AS purchase_cost_vnd,
                CASE
                    WHEN l.purchase_exchange_rate IS NOT NULL THEN round(l.shipping_rmb * l.purchase_exchange_rate, 2)
                    ELSE 0::numeric
                END AS cn_shipping_vnd,
            c.vn_shipping_vnd,
            c.repair_cost_vnd,
            c.upgrade_cost_vnd,
            c.accessory_cost_vnd,
            c.other_cost_vnd,
            c.refund_credit_vnd,
                CASE
                    WHEN l.source_type = 'UNKNOWN'::text THEN 'INCOMPLETE'::text
                    WHEN (l.source_type = ANY (ARRAY['SUPPLIER_PURCHASE'::text, 'SUPPLIER_REPLACEMENT'::text])) AND (l.purchase_batch_id IS NULL OR l.purchase_exchange_rate IS NULL) THEN 'INCOMPLETE'::text
                    WHEN l.source_type = 'TRADE_IN'::text AND COALESCE(c.trade_in_cost_vnd, 0::numeric) <= 0::numeric THEN 'INCOMPLETE'::text
                    WHEN (EXISTS ( SELECT 1
                       FROM repair_jobs r
                      WHERE r.laptop_id = l.id AND (r.status <> ALL (ARRAY['COMPLETED'::text, 'CANCELLED'::text])))) THEN 'INCOMPLETE'::text
                    ELSE 'COMPLETE'::text
                END AS cost_status
           FROM laptops l
             LEFT JOIN component_sums c ON c.laptop_id = l.id
        )
 SELECT id AS laptop_id,
    COALESCE(purchase_cost_vnd, 0::numeric)::numeric(18,2) AS purchase_cost_vnd,
    COALESCE(cn_shipping_vnd, 0::numeric)::numeric(18,2) AS cn_shipping_vnd,
    COALESCE(vn_shipping_vnd, 0::numeric)::numeric(18,2) AS vn_shipping_vnd,
    COALESCE(repair_cost_vnd, 0::numeric)::numeric(18,2) AS repair_cost_vnd,
    COALESCE(upgrade_cost_vnd, 0::numeric)::numeric(18,2) AS upgrade_cost_vnd,
    COALESCE(accessory_cost_vnd, 0::numeric)::numeric(18,2) AS accessory_cost_vnd,
    COALESCE(other_cost_vnd, 0::numeric)::numeric(18,2) AS other_cost_vnd,
    COALESCE(refund_credit_vnd, 0::numeric)::numeric(18,2) AS refund_credit_vnd,
    GREATEST(COALESCE(purchase_cost_vnd, 0::numeric) + COALESCE(cn_shipping_vnd, 0::numeric) + COALESCE(vn_shipping_vnd, 0::numeric) + COALESCE(repair_cost_vnd, 0::numeric) + COALESCE(upgrade_cost_vnd, 0::numeric) + COALESCE(accessory_cost_vnd, 0::numeric) + COALESCE(other_cost_vnd, 0::numeric) - COALESCE(refund_credit_vnd, 0::numeric), 0::numeric)::numeric(18,2) AS landed_cost_vnd,
    cost_status,
    array_remove(ARRAY[
        CASE
            WHEN source_type = 'UNKNOWN'::text THEN 'UNKNOWN_SOURCE'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (source_type = ANY (ARRAY['SUPPLIER_PURCHASE'::text, 'SUPPLIER_REPLACEMENT'::text])) AND purchase_batch_id IS NULL THEN 'MISSING_PURCHASE_BATCH'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (source_type = ANY (ARRAY['SUPPLIER_PURCHASE'::text, 'SUPPLIER_REPLACEMENT'::text])) AND purchase_exchange_rate IS NULL THEN 'MISSING_EXCHANGE_RATE'::text
            ELSE NULL::text
        END,
        CASE
            WHEN source_type = 'TRADE_IN'::text AND purchase_cost_vnd <= 0::numeric THEN 'MISSING_TRADE_IN_ACQUISITION'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM repair_jobs r
              WHERE r.laptop_id = calculated.id AND (r.status <> ALL (ARRAY['COMPLETED'::text, 'CANCELLED'::text])))) THEN 'ACTIVE_REPAIR_COST_PENDING'::text
            ELSE NULL::text
        END], NULL::text) AS reasons
   FROM calculated;;
CREATE VIEW public."unified_inventory" AS
 SELECT l.id::text AS entity_key,
    'LAPTOP'::text AS entity_type,
    l.id AS entity_id,
    l.id AS laptop_id,
    l.name,
    l.category,
    l.serial,
    l.tracking_code_cn,
    l.status AS display_status,
    l.status AS backend_status,
    s.name AS supplier_name,
    b.batch_code,
    l.received_at,
    l.warehouse_date,
    l.available_for_sale_at,
    b.purchase_date,
        CASE
            WHEN b.purchase_date IS NULL THEN NULL::text
            ELSE to_char(b.purchase_date::timestamp with time zone, 'MM/YYYY'::text)
        END AS month_key,
    l.purchase_price_rmb,
    l.shipping_rmb,
    l.purchase_exchange_rate AS exchange_rate,
    l.charger_status,
    l.battery_health,
    l.warranty_supplier,
        CASE
            WHEN l.purchase_exchange_rate IS NULL THEN NULL::numeric
            ELSE round((l.purchase_price_rmb + l.shipping_rmb) * l.purchase_exchange_rate, 2)
        END AS landed_cost_vnd,
    l.source_type = 'UNKNOWN'::text AS source_unresolved,
    l.condition_note AS notes
   FROM laptops l
     LEFT JOIN purchase_batches b ON b.id = l.purchase_batch_id
     LEFT JOIN suppliers s ON s.id = b.supplier_id;;

-- FUNCTIONS
CREATE OR REPLACE FUNCTION public.order_uses_laptop(p_laptop_id bigint, p_is_active boolean, p_order_status text, p_payment_status text, p_reservation_expires_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(
    p_laptop_id IS NOT NULL
    AND p_is_active IS TRUE
    AND COALESCE(p_payment_status, '') <> 'refunded'
    AND COALESCE(p_order_status, '') NOT IN ('cancelled', 'returned')
    AND (
      p_order_status IN ('prepared', 'shipping', 'done')
      OR (
        (p_order_status = 'deposited' OR p_payment_status = 'deposited')
        AND (p_reservation_expires_at IS NULL OR p_reservation_expires_at > CURRENT_TIMESTAMP)
      )
    ),
    false
  );
$function$;
CREATE OR REPLACE FUNCTION public.prevent_laptop_double_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.order_uses_laptop(
    NEW.laptop_id, NEW.is_active, NEW.order_status, NEW.payment_status, NEW.reservation_expires_at
  ) THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(NEW.laptop_id);
  IF EXISTS (
    SELECT 1
    FROM orders existing_order
    WHERE existing_order.laptop_id = NEW.laptop_id
      AND existing_order.id IS DISTINCT FROM NEW.id
      AND public.order_uses_laptop(
        existing_order.laptop_id,
        existing_order.is_active,
        existing_order.order_status,
        existing_order.payment_status,
        existing_order.reservation_expires_at
      )
  ) THEN
    RAISE EXCEPTION 'Laptop % is already reserved by another active order', NEW.laptop_id
      USING ERRCODE = '23505';
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  NEW.updated_at := timezone('utc'::text, now());
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.prevent_activity_log_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RAISE EXCEPTION 'activity_logs is append-only';
END;
$function$;
CREATE OR REPLACE FUNCTION public.deactivate_user(target_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF (SELECT role FROM user_profiles WHERE id = auth.uid()) = 'ADMIN' THEN
    UPDATE user_profiles SET is_active = false WHERE id = target_user_id;
  ELSE
    RAISE EXCEPTION 'Access denied';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.activate_user(target_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF (SELECT role FROM user_profiles WHERE id = auth.uid()) = 'ADMIN' THEN
    UPDATE user_profiles SET is_active = true WHERE id = target_user_id;
  ELSE
    RAISE EXCEPTION 'Access denied';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.normalize_order_financials(p_order orders)
 RETURNS orders
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_order orders := p_order;
BEGIN
  v_order.is_active := COALESCE(v_order.is_active, true);
  v_order.sale_price := GREATEST(COALESCE(v_order.sale_price, 0), 0);
  v_order.deposit_amount := LEAST(v_order.sale_price, GREATEST(COALESCE(v_order.deposit_amount, 0), 0));
  v_order.amount_paid := LEAST(v_order.sale_price, GREATEST(COALESCE(v_order.amount_paid, 0), v_order.deposit_amount));
  v_order.debt_amount := GREATEST(v_order.sale_price - v_order.amount_paid, 0);
  v_order.cod_amount := LEAST(v_order.sale_price, GREATEST(COALESCE(v_order.cod_amount, 0), 0));
  v_order.credit_card_fee := GREATEST(COALESCE(v_order.credit_card_fee, 0), 0);
  v_order.profit_vnd := COALESCE(v_order.profit_vnd, 0);
  v_order.payment_status := lower(btrim(COALESCE(v_order.payment_status, '')));
  IF v_order.payment_status NOT IN ('unpaid','deposited','cod','paid','refunded') THEN v_order.payment_status := 'unpaid'; END IF;
  IF v_order.laptop_id IS NOT NULL AND v_order.is_active IS TRUE
     AND v_order.reservation_expires_at IS NULL
     AND (v_order.order_status='deposited' OR v_order.payment_status='deposited') THEN
    v_order.reservation_expires_at := timezone('utc'::text,now()) + interval '48 hours';
  END IF;
  v_order.laptop_locked := public.order_uses_laptop(v_order.laptop_id,v_order.is_active,v_order.order_status,v_order.payment_status,v_order.reservation_expires_at);
  RETURN v_order;
END $function$;
CREATE OR REPLACE FUNCTION public.refresh_laptop_inventory(p_laptop_id bigint)
 RETURNS laptops
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE; has_committed boolean; has_reserved boolean;
BEGIN
  IF p_laptop_id IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO l FROM laptops WHERE id=p_laptop_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Laptop % khÃ´ng tá»“n táº¡i',p_laptop_id; END IF;
  UPDATE orders SET laptop_locked=public.order_uses_laptop(laptop_id,is_active,order_status,payment_status,reservation_expires_at)
  WHERE laptop_id=p_laptop_id AND laptop_locked IS DISTINCT FROM public.order_uses_laptop(laptop_id,is_active,order_status,payment_status,reservation_expires_at);
  SELECT exists(SELECT 1 FROM orders WHERE laptop_id=p_laptop_id
    AND public.order_uses_laptop(laptop_id,is_active,order_status,payment_status,reservation_expires_at)
    AND order_status IN('prepared','shipping','done')) INTO has_committed;
  SELECT exists(SELECT 1 FROM orders WHERE (laptop_id=p_laptop_id OR requested_laptop_id=p_laptop_id)
    AND is_active IS TRUE AND coalesce(payment_status,'')<>'refunded'
    AND coalesce(order_status,'') NOT IN('cancelled','returned')
    AND (public.order_uses_laptop(laptop_id,is_active,order_status,payment_status,reservation_expires_at)
      OR ((order_status='deposited' OR payment_status='deposited')
        AND (reservation_expires_at IS NULL OR reservation_expires_at>CURRENT_TIMESTAMP)))) INTO has_reserved;
  PERFORM set_config('app.laptop_transition','on',true);
  UPDATE laptops SET status=CASE
      WHEN status IN('in_transit','waiting_qc','repair','supplier_return','ignored') THEN status
      WHEN has_committed THEN 'sold'
      WHEN has_reserved THEN 'reserved'
      ELSE 'available' END,
    sold_at=CASE WHEN has_committed THEN coalesce(sold_at,timezone('utc',now())) ELSE sold_at END
  WHERE id=p_laptop_id RETURNING * INTO l;
  RETURN l;
END $function$;
CREATE OR REPLACE FUNCTION public.record_order_payment(p_order_id bigint, p_amount numeric, p_payment_type text, p_payment_method text DEFAULT 'transfer_cash'::text, p_payment_date date DEFAULT CURRENT_DATE, p_reference_code text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_recorded_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order orders%ROWTYPE;
  v_payment payments%ROWTYPE;
  v_financial financial_records%ROWTYPE;
  v_new_amount_paid NUMERIC;
  v_old_uses BOOLEAN;
  v_new_uses BOOLEAN;
  v_old_committed BOOLEAN;
  v_new_committed BOOLEAN;
  v_laptop laptops%ROWTYPE;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Payment amount must be greater than zero';
  END IF;
  IF p_payment_type NOT IN ('deposit', 'balance', 'cod', 'refund', 'other') THEN
    RAISE EXCEPTION 'Unsupported payment type';
  END IF;

  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order % does not exist', p_order_id;
  END IF;
  IF v_order.is_active IS NOT TRUE THEN
    RAISE EXCEPTION 'Cannot record payment for an inactive order';
  END IF;

  v_old_uses := public.order_uses_laptop(
    v_order.laptop_id,
    v_order.is_active,
    v_order.order_status,
    v_order.payment_status,
    v_order.reservation_expires_at
  );
  v_old_committed := v_old_uses AND v_order.order_status IN ('prepared', 'shipping', 'done');
  IF v_order.laptop_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(v_order.laptop_id);
  END IF;

  IF p_payment_type = 'refund' THEN
    IF p_amount > COALESCE(v_order.amount_paid, 0) THEN
      RAISE EXCEPTION 'Refund cannot exceed amount already paid';
    END IF;
    v_new_amount_paid := GREATEST(COALESCE(v_order.amount_paid, 0) - p_amount, 0);
    v_order.deposit_amount := LEAST(COALESCE(v_order.deposit_amount, 0), v_new_amount_paid);
    IF v_new_amount_paid = 0 THEN
      v_order.payment_status := 'refunded';
    END IF;
  ELSE
    IF COALESCE(v_order.amount_paid, 0) + p_amount > COALESCE(v_order.sale_price, 0) THEN
      RAISE EXCEPTION 'Payment exceeds order sale price';
    END IF;
    v_new_amount_paid := COALESCE(v_order.amount_paid, 0) + p_amount;
    v_order.amount_paid := v_new_amount_paid;
    IF p_payment_type = 'deposit' THEN
      v_order.deposit_amount := COALESCE(v_order.deposit_amount, 0) + p_amount;
    ELSIF p_payment_type = 'cod' THEN
      v_order.payment_status := 'cod';
    END IF;
  END IF;

  v_order.amount_paid := v_new_amount_paid;
  v_order := public.normalize_order_financials(v_order);

  INSERT INTO payments (
    order_id, payment_type, amount, payment_method, payment_date,
    reference_code, note, recorded_by
  ) VALUES (
    p_order_id,
    p_payment_type,
    p_amount,
    COALESCE(NULLIF(btrim(p_payment_method), ''), 'transfer_cash'),
    COALESCE(p_payment_date, CURRENT_DATE),
    p_reference_code,
    p_note,
    p_recorded_by
  ) RETURNING * INTO v_payment;

  INSERT INTO financial_records (
    record_type, category, amount, order_id, payment_id, occurred_on,
    payment_method, note, recorded_by
  ) VALUES (
    CASE WHEN p_payment_type = 'refund' THEN 'refund' ELSE 'income' END,
    p_payment_type,
    p_amount,
    p_order_id,
    v_payment.id,
    COALESCE(p_payment_date, CURRENT_DATE),
    COALESCE(NULLIF(btrim(p_payment_method), ''), 'transfer_cash'),
    p_note,
    p_recorded_by
  ) RETURNING * INTO v_financial;

  UPDATE orders
  SET amount_paid = v_order.amount_paid,
      deposit_amount = v_order.deposit_amount,
      debt_amount = v_order.debt_amount,
      payment_status = v_order.payment_status,
      laptop_locked = v_order.laptop_locked,
      updated_at = timezone('utc'::text, now())
  WHERE id = p_order_id
  RETURNING * INTO v_order;

  v_new_uses := public.order_uses_laptop(
    v_order.laptop_id,
    v_order.is_active,
    v_order.order_status,
    v_order.payment_status,
    v_order.reservation_expires_at
  );
  v_new_committed := v_new_uses AND v_order.order_status IN ('prepared', 'shipping', 'done');
  IF v_order.laptop_id IS NOT NULL THEN
    v_laptop := public.refresh_laptop_inventory(v_order.laptop_id);
    IF v_old_uses IS DISTINCT FROM v_new_uses
       OR v_old_committed IS DISTINCT FROM v_new_committed THEN
      INSERT INTO stock_movements (laptop_id, order_id, movement_type, note, performed_by)
      VALUES (
        v_order.laptop_id,
        v_order.id,
        CASE
          WHEN NOT v_new_uses THEN 'RELEASED'
          WHEN v_new_committed THEN 'SOLD'
          ELSE 'RESERVED'
        END,
        'Laptop state synchronized by payment',
        p_recorded_by
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'payment', to_jsonb(v_payment),
    'financial_record', to_jsonb(v_financial),
    'order', to_jsonb(v_order),
    'laptop', CASE WHEN v_laptop.id IS NULL THEN NULL ELSE to_jsonb(v_laptop) END
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_order_before_invoice(p_order jsonb, p_recorded_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_input orders%ROWTYPE;
  v_order orders%ROWTYPE;
  v_laptop laptops%ROWTYPE;
  v_payment payments%ROWTYPE;
  v_initial_deposit NUMERIC;
  v_initial_balance NUMERIC;
  v_created_payments JSONB := '[]'::jsonb;
BEGIN
  IF p_order IS NULL THEN RAISE EXCEPTION 'Order data is required'; END IF;
  v_input := jsonb_populate_record(NULL::orders, p_order);
  v_input.created_at := COALESCE(v_input.created_at, timezone('utc'::text, now()));
  v_input.updated_at := COALESCE(v_input.updated_at, timezone('utc'::text, now()));
  v_input := public.normalize_order_financials(v_input);
  IF v_input.month_key IS NULL OR btrim(v_input.month_key) = '' THEN
    v_input.month_key := TO_CHAR(CURRENT_DATE, 'MM/YYYY');
  END IF;

  INSERT INTO orders (
    created_date, sale_online, sale_offline, note, order_type, order_status,
    payment_status, payment_method, delivery_status, shipping_method, laptop_id,
    sale_price, deposit_amount, deposit_note, cod_amount, amount_paid, debt_amount,
    credit_card_fee, profit_vnd, trade_in_laptop_id, customer_id, customer_info,
    customer_address, tracking_code, ship_date, setup_note, warranty,
    laptop_locked, reservation_expires_at, cancel_reason, cancelled_at,
    returned_at, return_reason, is_active, month_key, created_at, updated_at
  ) VALUES (
    v_input.created_date, v_input.sale_online, v_input.sale_offline, v_input.note,
    v_input.order_type, v_input.order_status, v_input.payment_status,
    v_input.payment_method, v_input.delivery_status, v_input.shipping_method,
    v_input.laptop_id, v_input.sale_price, v_input.deposit_amount, v_input.deposit_note,
    v_input.cod_amount, v_input.amount_paid, v_input.debt_amount, v_input.credit_card_fee,
    v_input.profit_vnd, v_input.trade_in_laptop_id, v_input.customer_id,
    v_input.customer_info, v_input.customer_address, v_input.tracking_code,
    v_input.ship_date, v_input.setup_note, v_input.warranty, v_input.laptop_locked,
    v_input.reservation_expires_at, v_input.cancel_reason, v_input.cancelled_at,
    v_input.returned_at, v_input.return_reason, v_input.is_active, v_input.month_key,
    v_input.created_at, v_input.updated_at
  ) RETURNING * INTO v_order;

  v_initial_deposit := LEAST(COALESCE(v_order.deposit_amount, 0), COALESCE(v_order.amount_paid, 0));
  v_initial_balance := GREATEST(COALESCE(v_order.amount_paid, 0) - v_initial_deposit, 0);
  IF v_initial_deposit > 0 THEN
    INSERT INTO payments(order_id,payment_type,amount,payment_method,payment_date,note,recorded_by)
    VALUES(v_order.id,'deposit',v_initial_deposit,COALESCE(NULLIF(btrim(v_order.payment_method),''),'transfer_cash'),COALESCE(v_order.created_date,CURRENT_DATE),v_order.deposit_note,p_recorded_by)
    RETURNING * INTO v_payment;
    v_created_payments := v_created_payments || jsonb_build_array(to_jsonb(v_payment));
    INSERT INTO financial_records(record_type,category,amount,order_id,payment_id,occurred_on,payment_method,note,recorded_by)
    VALUES('income','deposit',v_initial_deposit,v_order.id,v_payment.id,COALESCE(v_order.created_date,CURRENT_DATE),COALESCE(NULLIF(btrim(v_order.payment_method),''),'transfer_cash'),v_order.deposit_note,p_recorded_by);
  END IF;
  IF v_initial_balance > 0 THEN
    INSERT INTO payments(order_id,payment_type,amount,payment_method,payment_date,note,recorded_by)
    VALUES(v_order.id,CASE WHEN v_order.payment_status='cod' THEN 'cod' ELSE 'balance' END,v_initial_balance,COALESCE(NULLIF(btrim(v_order.payment_method),''),'transfer_cash'),COALESCE(v_order.created_date,CURRENT_DATE),'Initial payment recorded with order',p_recorded_by)
    RETURNING * INTO v_payment;
    v_created_payments := v_created_payments || jsonb_build_array(to_jsonb(v_payment));
    INSERT INTO financial_records(record_type,category,amount,order_id,payment_id,occurred_on,payment_method,note,recorded_by)
    VALUES('income',CASE WHEN v_order.payment_status='cod' THEN 'cod' ELSE 'balance' END,v_initial_balance,v_order.id,v_payment.id,COALESCE(v_order.created_date,CURRENT_DATE),COALESCE(NULLIF(btrim(v_order.payment_method),''),'transfer_cash'),'Initial payment recorded with order',p_recorded_by);
  END IF;
  IF v_order.laptop_id IS NOT NULL THEN
    v_laptop := public.refresh_laptop_inventory(v_order.laptop_id);
    IF v_order.laptop_locked IS TRUE THEN
      INSERT INTO stock_movements(laptop_id,order_id,movement_type,note,performed_by)
      VALUES(v_order.laptop_id,v_order.id,CASE WHEN v_order.order_status IN ('prepared','shipping','done') THEN 'SOLD' ELSE 'RESERVED' END,'Inventory updated by order transaction',p_recorded_by);
    END IF;
  END IF;
  RETURN jsonb_build_object('order',to_jsonb(v_order),'laptop',CASE WHEN v_laptop.id IS NULL THEN NULL ELSE to_jsonb(v_laptop) END,'payments',v_created_payments,'inventory_applied',true);
END;
$function$;
CREATE OR REPLACE FUNCTION public.update_order_before_invoice(p_order jsonb, p_recorded_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order_id BIGINT;
  v_existing orders%ROWTYPE;
  v_next orders%ROWTYPE;
  v_order orders%ROWTYPE;
  v_old_laptop laptops%ROWTYPE;
  v_previous_laptop laptops%ROWTYPE;
  v_laptop laptops%ROWTYPE;
  v_old_laptop_id BIGINT;
  v_new_laptop_id BIGINT;
BEGIN
  IF p_order IS NULL OR NOT (p_order ? 'id') THEN
    RAISE EXCEPTION 'Order id is required';
  END IF;

  v_order_id := (p_order->>'id')::BIGINT;
  SELECT * INTO v_existing FROM orders WHERE id = v_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order % does not exist', v_order_id;
  END IF;

  v_next := jsonb_populate_record(v_existing, p_order);
  v_next.id := v_existing.id;
  v_next.created_at := COALESCE(v_next.created_at, v_existing.created_at);
  v_next.updated_at := timezone('utc'::text, now());
  v_next := public.normalize_order_financials(v_next);
  IF v_next.month_key IS NULL OR btrim(v_next.month_key) = '' THEN
    v_next.month_key := COALESCE(v_existing.month_key, TO_CHAR(CURRENT_DATE, 'MM/YYYY'));
  END IF;

  v_old_laptop_id := v_existing.laptop_id;
  v_new_laptop_id := v_next.laptop_id;
  IF v_old_laptop_id IS NOT NULL AND v_new_laptop_id IS NOT NULL AND v_old_laptop_id <> v_new_laptop_id THEN
    IF v_old_laptop_id < v_new_laptop_id THEN
      PERFORM pg_advisory_xact_lock(v_old_laptop_id);
      PERFORM pg_advisory_xact_lock(v_new_laptop_id);
    ELSE
      PERFORM pg_advisory_xact_lock(v_new_laptop_id);
      PERFORM pg_advisory_xact_lock(v_old_laptop_id);
    END IF;
  ELSIF v_old_laptop_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(v_old_laptop_id);
  ELSIF v_new_laptop_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(v_new_laptop_id);
  END IF;

  IF v_old_laptop_id IS NOT NULL THEN
    SELECT * INTO v_old_laptop FROM laptops WHERE id = v_old_laptop_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Laptop % does not exist', v_old_laptop_id; END IF;
  END IF;
  IF v_new_laptop_id IS NOT NULL AND v_new_laptop_id <> v_old_laptop_id THEN
    SELECT * INTO v_laptop FROM laptops WHERE id = v_new_laptop_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Laptop % does not exist', v_new_laptop_id; END IF;
  END IF;

  UPDATE orders SET
    created_date = v_next.created_date,
    sale_online = v_next.sale_online,
    sale_offline = v_next.sale_offline,
    note = v_next.note,
    order_type = v_next.order_type,
    order_status = v_next.order_status,
    payment_status = v_next.payment_status,
    payment_method = v_next.payment_method,
    delivery_status = v_next.delivery_status,
    shipping_method = v_next.shipping_method,
    laptop_id = v_next.laptop_id,
    sale_price = v_next.sale_price,
    deposit_amount = v_next.deposit_amount,
    deposit_note = v_next.deposit_note,
    cod_amount = v_next.cod_amount,
    amount_paid = v_next.amount_paid,
    debt_amount = v_next.debt_amount,
    credit_card_fee = v_next.credit_card_fee,
    profit_vnd = v_next.profit_vnd,
    trade_in_laptop_id = v_next.trade_in_laptop_id,
    customer_id = v_next.customer_id,
    customer_info = v_next.customer_info,
    customer_address = v_next.customer_address,
    tracking_code = v_next.tracking_code,
    ship_date = v_next.ship_date,
    setup_note = v_next.setup_note,
    warranty = v_next.warranty,
    laptop_locked = v_next.laptop_locked,
    reservation_expires_at = v_next.reservation_expires_at,
    cancel_reason = v_next.cancel_reason,
    cancelled_at = v_next.cancelled_at,
    returned_at = v_next.returned_at,
    return_reason = v_next.return_reason,
    is_active = v_next.is_active,
    month_key = v_next.month_key,
    updated_at = v_next.updated_at
  WHERE id = v_order_id
  RETURNING * INTO v_order;

  IF v_old_laptop_id IS NOT NULL AND (v_new_laptop_id IS NULL OR v_new_laptop_id <> v_old_laptop_id) THEN
    v_previous_laptop := public.refresh_laptop_inventory(v_old_laptop_id);
  END IF;
  IF v_new_laptop_id IS NOT NULL THEN
    v_laptop := public.refresh_laptop_inventory(v_new_laptop_id);
  END IF;

  IF v_old_laptop_id IS NOT NULL AND (v_new_laptop_id IS NULL OR v_new_laptop_id <> v_old_laptop_id) THEN
    INSERT INTO stock_movements (laptop_id, order_id, movement_type, note, performed_by)
    VALUES (v_old_laptop_id, v_order.id, 'UNRESERVED', 'Laptop unlinked from order', p_recorded_by);
  END IF;
  IF v_new_laptop_id IS NOT NULL AND v_new_laptop_id <> v_old_laptop_id THEN
    INSERT INTO stock_movements (laptop_id, order_id, movement_type, note, performed_by)
    VALUES (
      v_new_laptop_id, v_order.id,
      CASE WHEN v_order.order_status IN ('prepared', 'shipping', 'done') THEN 'SOLD' ELSE 'RESERVED' END,
      'Laptop linked to order', p_recorded_by
    );
  END IF;

  RETURN jsonb_build_object(
    'order', to_jsonb(v_order),
    'laptop', CASE WHEN v_laptop.id IS NULL THEN NULL ELSE to_jsonb(v_laptop) END,
    'payments', '[]'::jsonb,
    'inventory_applied', true
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.save_order_invoice_fields(p_order jsonb, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id bigint := (p_result->'order'->>'id')::bigint; v_row orders%ROWTYPE;
BEGIN
 IF p_order ? 'gift_accessory_ids' AND (jsonb_typeof(p_order->'gift_accessory_ids') <> 'array' OR jsonb_array_length(p_order->'gift_accessory_ids') > 30) THEN
   RAISE EXCEPTION 'Danh sÃ¡ch quÃ  táº·ng khÃ´ng há»£p lá»‡';
 END IF;
 IF p_order ? 'gift_accessory_ids' AND EXISTS (
   SELECT 1 FROM jsonb_array_elements_text(p_order->'gift_accessory_ids') x(id)
   WHERE NOT EXISTS (SELECT 1 FROM accessories a WHERE a.id::text = x.id AND a.active)
 ) THEN RAISE EXCEPTION 'Phá»¥ kiá»‡n khÃ´ng tá»“n táº¡i hoáº·c Ä‘Ã£ ngá»«ng sá»­ dá»¥ng'; END IF;
 UPDATE orders SET
   branch_id = CASE WHEN p_order ? 'branch_id' THEN (p_order->>'branch_id')::bigint ELSE branch_id END,
   gift_accessory_ids = CASE WHEN p_order ? 'gift_accessory_ids' THEN p_order->'gift_accessory_ids' ELSE gift_accessory_ids END,
   gift_preset = CASE WHEN p_order ? 'gift_preset' THEN coalesce(p_order->>'gift_preset','') ELSE gift_preset END
 WHERE id = v_id RETURNING * INTO v_row;
 RETURN jsonb_set(p_result,'{order}',to_jsonb(v_row));
END $function$;
CREATE OR REPLACE FUNCTION public.create_order_with_inventory(p_order jsonb, p_recorded_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN RETURN save_order_invoice_fields(p_order,create_order_before_invoice(p_order,p_recorded_by)); END $function$;
CREATE OR REPLACE FUNCTION public.update_order_with_inventory(p_order jsonb, p_recorded_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN RETURN save_order_invoice_fields(p_order,update_order_before_invoice(p_order,p_recorded_by)); END $function$;
CREATE OR REPLACE FUNCTION public.issue_invoice(p_order_id bigint, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE o orders%ROWTYPE; l laptops%ROWTYPE; c customers%ROWTYPE; b branches%ROWTYPE;
 i invoices%ROWTYPE; items jsonb; receipts jsonb; finance jsonb; ledger_total numeric; effective_paid numeric; deposit_total numeric; a accessories%ROWTYPE;
BEGIN
 SELECT * INTO o FROM orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'KhÃ´ng tÃ¬m tháº¥y Ä‘Æ¡n hÃ ng'; END IF;
 SELECT * INTO i FROM invoices WHERE order_id=p_order_id;
 IF FOUND THEN RETURN to_jsonb(i); END IF;
 IF o.is_active IS NOT TRUE OR o.order_status NOT IN ('shipping','done') THEN
   RAISE EXCEPTION 'Chá»‰ xuáº¥t hÃ³a Ä‘Æ¡n khi Ä‘Æ¡n Ä‘ang giao hÃ ng hoáº·c Ä‘Ã£ hoÃ n thÃ nh';
 END IF;
 IF coalesce(o.sale_price,0) <= 0 THEN
   RAISE EXCEPTION 'ÄÆ¡n hÃ ng chÆ°a cÃ³ giÃ¡ bÃ¡n há»£p lá»‡';
 END IF;
 SELECT * INTO b FROM branches WHERE id=o.branch_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Vui lÃ²ng chá»n chi nhÃ¡nh bÃ¡n hÃ ng trong Ä‘Æ¡n'; END IF;
 SELECT * INTO l FROM laptops WHERE id=o.laptop_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ÄÆ¡n chÆ°a cÃ³ laptop'; END IF;
 SELECT * INTO c FROM customers WHERE id=o.customer_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Vui lÃ²ng chá»n khÃ¡ch hÃ ng cÃ³ tÃªn, SÄT vÃ  Ä‘á»‹a chá»‰'; END IF;
 IF coalesce(btrim(c.name),'')='' OR coalesce(btrim(c.phone),'')='' THEN RAISE EXCEPTION 'KhÃ¡ch hÃ ng thiáº¿u tÃªn hoáº·c sá»‘ Ä‘iá»‡n thoáº¡i'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.payment_date,p.id),'[]'),
 coalesce(sum(CASE WHEN p.payment_type='refund' THEN -p.amount ELSE p.amount END),0),
 coalesce(sum(CASE WHEN p.payment_type='deposit' THEN p.amount ELSE 0 END),0)
 INTO receipts,ledger_total,deposit_total FROM payments p WHERE p.order_id=o.id;
 effective_paid := greatest(ledger_total,coalesce(o.amount_paid,0));
 IF (deposit_total <= 0 AND coalesce(o.deposit_amount,0) <= 0
     AND NOT (o.payment_status='paid' AND coalesce(o.amount_paid,0) > 0))
    OR effective_paid <= 0 THEN
   RAISE EXCEPTION 'Cáº§n ghi nháº­n Ã­t nháº¥t má»™t khoáº£n Ä‘áº·t cá»c trÆ°á»›c khi xuáº¥t hÃ³a Ä‘Æ¡n';
 END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(f) ORDER BY f.occurred_on,f.id),'[]') INTO finance FROM financial_records f WHERE f.order_id=o.id;
 items := jsonb_build_array(jsonb_build_object('kind','laptop','id',l.id,'sku',l.sku,'name',l.name,'quantity',1,'price',o.sale_price,'total',o.sale_price,'serial',l.serial,'note',concat_ws(' Â· ',l.condition_note,o.warranty,o.setup_note)));
 FOR a IN SELECT * FROM accessories WHERE id IN (SELECT value::bigint FROM jsonb_array_elements_text(o.gift_accessory_ids)) ORDER BY id LOOP
   items := items || jsonb_build_array(jsonb_build_object('kind','gift','id',a.id,'sku',a.sku,'name',a.name,'quantity',1,'price',0,'total',0,'serial','','note',a.note));
 END LOOP;
 INSERT INTO invoices(order_id,laptop_id,customer_id,created_by,snapshot) VALUES
 (o.id,l.id,c.id,p_actor,jsonb_build_object('order',to_jsonb(o),'customer',to_jsonb(c),'branch',to_jsonb(b),'items',items,'payments',receipts,'financial_records',finance,'total',o.sale_price,'paid',effective_paid,'currency','VND','unit_multiplier',1000000)) RETURNING * INTO i;
 RETURN to_jsonb(i);
END $function$;
CREATE OR REPLACE FUNCTION public.sync_invoice_payment_snapshot(p_order_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE receipts jsonb; finance jsonb; ledger_total numeric; effective_paid numeric; payment_count bigint; current_order orders%ROWTYPE;
BEGIN
 SELECT * INTO current_order FROM orders WHERE id=p_order_id;
 IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM invoices WHERE order_id=p_order_id) THEN RETURN; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.payment_date,p.id),'[]'),
        coalesce(sum(CASE WHEN p.payment_type='refund' THEN -p.amount ELSE p.amount END),0),
        count(*)
 INTO receipts,ledger_total,payment_count FROM payments p WHERE p.order_id=p_order_id;
 effective_paid := CASE WHEN payment_count > 0 THEN ledger_total ELSE coalesce(current_order.amount_paid,0) END;
 SELECT coalesce(jsonb_agg(to_jsonb(f) ORDER BY f.occurred_on,f.id),'[]')
 INTO finance FROM financial_records f WHERE f.order_id=p_order_id;
 UPDATE invoices SET snapshot = jsonb_set(
   jsonb_set(
     jsonb_set(
       jsonb_set(
         jsonb_set(
           jsonb_set(
             jsonb_set(snapshot,'{payments}',receipts,true),
             '{financial_records}',finance,true),
           '{paid}',to_jsonb(effective_paid),true),
         '{order,payment_status}',to_jsonb(current_order.payment_status),true),
       '{order,amount_paid}',to_jsonb(coalesce(current_order.amount_paid,ledger_total)),true),
     '{order,trade_in_credit_vnd}',to_jsonb(coalesce(current_order.trade_in_credit_vnd,0)),true),
   '{order,debt_amount}',to_jsonb(coalesce(current_order.debt_amount,0)),true)
 WHERE order_id=p_order_id;
END $function$;
CREATE OR REPLACE FUNCTION public.sync_invoice_payment_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP = 'DELETE' THEN
   PERFORM sync_invoice_payment_snapshot(OLD.order_id);
   RETURN OLD;
 END IF;
 PERFORM sync_invoice_payment_snapshot(NEW.order_id);
 RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.sync_invoice_order_payment_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN PERFORM sync_invoice_payment_snapshot(NEW.id); RETURN NEW; END $function$;
CREATE OR REPLACE FUNCTION public.next_purchase_batch_code(p_date date DEFAULT CURRENT_DATE)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE prefix text:='PO-'||to_char(p_date,'YYYYMMDD')||'-'; n integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext(prefix));
  SELECT coalesce(max(right(batch_code,3)::integer),0)+1 INTO n
  FROM purchase_batches WHERE batch_code LIKE prefix||'%';
  RETURN prefix||lpad(n::text,3,'0');
END $function$;
CREATE OR REPLACE FUNCTION public.record_supplier_payment(p_batch_id bigint, p_amount_rmb numeric, p_exchange_rate numeric, p_method text, p_reference text, p_date date, p_notes text, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE b purchase_batches%ROWTYPE; paid numeric; total numeric; result supplier_payments%ROWTYPE;
BEGIN
  SELECT * INTO result FROM supplier_payments WHERE idempotency_key=p_idempotency_key;
  IF FOUND THEN RETURN to_jsonb(result); END IF;
  IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 90 THEN
    RAISE EXCEPTION 'Idempotency key khÃ´ng há»£p lá»‡';
  END IF;
  SELECT * INTO b FROM purchase_batches WHERE id=p_batch_id FOR UPDATE;
  IF NOT FOUND OR b.active IS NOT TRUE OR b.status='CANCELLED' THEN
    RAISE EXCEPTION 'LÃ´ mua khÃ´ng tá»“n táº¡i hoáº·c khÃ´ng cÃ²n nháº­n thanh toÃ¡n';
  END IF;
  SELECT coalesce(sum(purchase_price_rmb),0) INTO total
  FROM laptops WHERE purchase_batch_id=b.id AND status<>'ignored';
  SELECT coalesce(sum(amount_rmb),0) INTO paid
  FROM supplier_payments WHERE purchase_batch_id=b.id;
  IF p_amount_rmb IS NULL OR p_amount_rmb<=0 OR p_amount_rmb>total-paid THEN
    RAISE EXCEPTION 'Sá»‘ tiá»n vÆ°á»£t cÃ´ng ná»£ cÃ²n láº¡i';
  END IF;
  IF p_exchange_rate IS NULL OR p_exchange_rate<=0 THEN RAISE EXCEPTION 'Tá»· giÃ¡ khÃ´ng há»£p lá»‡'; END IF;
  IF p_method NOT IN('WECHAT','ALIPAY','BANK_TRANSFER','CASH','OTHER') THEN
    RAISE EXCEPTION 'PhÆ°Æ¡ng thá»©c thanh toÃ¡n khÃ´ng há»£p lá»‡';
  END IF;
  INSERT INTO supplier_payments(
    supplier_id,purchase_batch_id,amount_rmb,amount_vnd,exchange_rate,payment_method,
    reference,payment_date,notes,recorded_by,idempotency_key
  ) VALUES(
    b.supplier_id,b.id,p_amount_rmb,round(p_amount_rmb*p_exchange_rate,2),p_exchange_rate,
    p_method,left(coalesce(p_reference,''),200),coalesce(p_date,current_date),
    left(coalesce(p_notes,''),2000),p_actor,p_idempotency_key
  ) RETURNING * INTO result;
  RETURN to_jsonb(result);
EXCEPTION WHEN unique_violation THEN
  SELECT * INTO result FROM supplier_payments WHERE idempotency_key=p_idempotency_key;
  IF FOUND THEN RETURN to_jsonb(result); END IF;
  RAISE;
END $function$;
CREATE OR REPLACE FUNCTION public.guard_confirmed_purchase_batch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF OLD.status<>'DRAFT' AND (
    NEW.supplier_id IS DISTINCT FROM OLD.supplier_id OR NEW.purchase_date IS DISTINCT FROM OLD.purchase_date OR
    NEW.exchange_rate IS DISTINCT FROM OLD.exchange_rate OR NEW.subtotal_rmb IS DISTINCT FROM OLD.subtotal_rmb OR
    NEW.domestic_shipping_rmb IS DISTINCT FROM OLD.domestic_shipping_rmb OR NEW.other_cost_rmb IS DISTINCT FROM OLD.other_cost_rmb OR
    NEW.destination IS DISTINCT FROM OLD.destination
  ) THEN RAISE EXCEPTION 'KhÃ´ng thá»ƒ thay Ä‘á»•i thÃ´ng tin tÃ i chÃ­nh cá»§a lÃ´ Ä‘Ã£ xÃ¡c nháº­n'; END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.prevent_supplier_payment_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND current_setting('app.financial_account_link',true)='on' AND OLD.account_id IS NULL AND NEW.account_id IS NOT NULL
   AND (to_jsonb(NEW)-'account_id')=(to_jsonb(OLD)-'account_id') THEN RETURN NEW;END IF;
 RAISE EXCEPTION 'Thanh toÃ¡n nhÃ  cung cáº¥p lÃ  sá»• báº¥t biáº¿n; hÃ£y táº¡o giao dá»‹ch Ä‘iá»u chá»‰nh';
END $function$;
CREATE OR REPLACE FUNCTION public.guard_order_sellable_laptop()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE candidate_id bigint; candidate_status text;
BEGIN
  candidate_id:=coalesce(NEW.laptop_id,NEW.requested_laptop_id);
  IF candidate_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND candidate_id=coalesce(OLD.laptop_id,OLD.requested_laptop_id)
     AND NEW.laptop_id IS NOT DISTINCT FROM OLD.laptop_id
     AND NEW.requested_laptop_id IS NOT DISTINCT FROM OLD.requested_laptop_id THEN RETURN NEW; END IF;
  SELECT status INTO candidate_status FROM laptops WHERE id=candidate_id AND is_active IS TRUE FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Laptop khÃ´ng tá»“n táº¡i hoáº·c Ä‘Ã£ ngá»«ng sá»­ dá»¥ng'; END IF;
  IF candidate_status NOT IN('available','reserved') THEN
    RAISE EXCEPTION 'Laptop chÆ°a sáºµn sÃ ng Ä‘á»ƒ bÃ¡n (tráº¡ng thÃ¡i: %)',candidate_status;
  END IF;
  RETURN NEW;
END $function$;
