CREATE OR REPLACE FUNCTION public.start_qc_inspection(p_laptop_id bigint, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE; q qc_inspections%ROWTYPE;
BEGIN
 SELECT * INTO q FROM qc_inspections WHERE idempotency_key=p_idempotency_key;
 IF FOUND THEN RETURN to_jsonb(q); END IF;
 IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100 THEN RAISE EXCEPTION 'Idempotency key khÃ´ng há»£p lá»‡'; END IF;
 SELECT * INTO l FROM laptops WHERE id=p_laptop_id AND is_active IS TRUE FOR UPDATE;
 IF NOT FOUND OR l.status<>'waiting_qc' THEN RAISE EXCEPTION 'Laptop khÃ´ng á»Ÿ tráº¡ng thÃ¡i Chá» QC'; END IF;
 IF EXISTS(SELECT 1 FROM qc_inspections WHERE laptop_id=l.id AND status='IN_PROGRESS') THEN RAISE EXCEPTION 'Laptop Ä‘ang cÃ³ phiÃªn QC hoáº¡t Ä‘á»™ng'; END IF;
 INSERT INTO qc_inspections(inspection_code,laptop_id,started_by,idempotency_key)
 VALUES(next_qc_inspection_code(),l.id,p_actor,p_idempotency_key) RETURNING * INTO q;
 PERFORM seed_qc_checklist(q.id,p_actor);
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
 VALUES('QC_INSPECTION',q.id::text,'CREATE',jsonb_build_object('inspection_code',q.inspection_code,'laptop_id',l.id),p_actor);
 RETURN to_jsonb(q);
EXCEPTION WHEN unique_violation THEN
 SELECT * INTO q FROM qc_inspections WHERE idempotency_key=p_idempotency_key;
 IF FOUND THEN RETURN to_jsonb(q); END IF; RAISE;
END $function$;
CREATE OR REPLACE FUNCTION public.seed_qc_checklist(p_inspection_id uuid, p_actor text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  INSERT INTO qc_check_items(qc_inspection_id,check_key,label,category,requirement,sort_order,result,checked_by)
  SELECT p_inspection_id,x.key,x.label,x.category,x.requirement,x.ord,'NOT_TESTED',p_actor FROM (VALUES
    ('serial','Serial','IDENTITY','REQUIRED',10),('model','Model','IDENTITY','REQUIRED',20),
    ('cpu','CPU','CONFIGURATION','REQUIRED',30),('gpu','GPU','CONFIGURATION','REQUIRED',40),('ram','RAM','CONFIGURATION','REQUIRED',50),('ssd','SSD','CONFIGURATION','REQUIRED',60),
    ('mainboard','Mainboard','MAINBOARD','REQUIRED',70),('screen','MÃ n hÃ¬nh','DISPLAY','REQUIRED',80),
    ('keyboard','BÃ n phÃ­m','INPUT','REQUIRED',90),('keyboard_backlight','ÄÃ¨n bÃ n phÃ­m','INPUT','CONDITIONAL',100),('touchpad','Touchpad','INPUT','REQUIRED',110),
    ('camera','Camera','CAMERA_AUDIO','CONDITIONAL',120),('speaker','Loa','CAMERA_AUDIO','OPTIONAL',130),('microphone','Microphone','CAMERA_AUDIO','OPTIONAL',140),
    ('wifi','Wi-Fi','CONNECTIVITY','REQUIRED',150),('bluetooth','Bluetooth','CONNECTIVITY','CONDITIONAL',160),
    ('usb','USB','PORTS','OPTIONAL',170),('usb_c','USB-C','PORTS','CONDITIONAL',180),('hdmi','HDMI','PORTS','CONDITIONAL',190),('lan','LAN','PORTS','CONDITIONAL',200),
    ('battery','Pin','BATTERY_POWER','OPTIONAL',210),('ssd_health','Sá»©c khá»e SSD','STORAGE_MEMORY','REQUIRED',220),
    ('fan','Quáº¡t','THERMAL','REQUIRED',230),('cooling','Táº£n nhiá»‡t','THERMAL','OPTIONAL',240),
    ('cpu_stress','CPU stress','STRESS','REQUIRED',250),('gpu_stress','GPU stress','STRESS','REQUIRED',260),
    ('charger','Sáº¡c','CHARGER','REQUIRED',270),('exterior','Ngoáº¡i hÃ¬nh','COSMETIC','OPTIONAL',280)
  ) AS x(key,label,category,requirement,ord)
  ON CONFLICT(qc_inspection_id,check_key) DO NOTHING;
END $function$;
CREATE OR REPLACE FUNCTION public.save_qc_checklist(p_inspection_id uuid, p_items jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE q qc_inspections%ROWTYPE; item jsonb;
BEGIN
  SELECT * INTO q FROM qc_inspections WHERE id=p_inspection_id FOR UPDATE;
  IF NOT FOUND OR q.status<>'IN_PROGRESS' THEN RAISE EXCEPTION 'Chá»‰ cÃ³ thá»ƒ cáº­p nháº­t phiÃªn QC Ä‘ang thá»±c hiá»‡n'; END IF;
  IF jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'Checklist QC khÃ´ng há»£p lá»‡'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    IF coalesce(item->>'result','') NOT IN('PASS','FAIL','WARNING','NOT_TESTED','NOT_APPLICABLE') THEN RAISE EXCEPTION 'Káº¿t quáº£ checklist khÃ´ng há»£p lá»‡'; END IF;
    IF item->>'result' IN('FAIL','WARNING') AND btrim(coalesce(item->>'note',''))='' THEN RAISE EXCEPTION 'Má»¥c FAIL/WARNING pháº£i cÃ³ ghi chÃº (%)',item->>'check_key'; END IF;
    UPDATE qc_check_items SET result=item->>'result',note=left(coalesce(item->>'note',''),1000),checked_by=p_actor,checked_at=timezone('utc',now()) WHERE qc_inspection_id=q.id AND check_key=item->>'check_key';
    IF NOT FOUND THEN RAISE EXCEPTION 'Má»¥c checklist khÃ´ng thuá»™c inspection (%)',item->>'check_key'; END IF;
  END LOOP;
  RETURN jsonb_build_object('inspection_id',q.id,'updated',jsonb_array_length(p_items));
END $function$;
CREATE OR REPLACE FUNCTION public.complete_qc_inspection(p_inspection_id uuid, p_result text, p_mainboard_status text, p_charger_status text, p_cosmetic_grade text, p_notes text, p_items jsonb, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE q qc_inspections%ROWTYPE; l laptops%ROWTYPE; failed_keys text; incomplete_keys text;
BEGIN
 SELECT * INTO q FROM qc_inspections WHERE id=p_inspection_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'KhÃ´ng tÃ¬m tháº¥y phiÃªn QC'; END IF;
 IF q.status='COMPLETED' AND q.completion_idempotency_key=p_idempotency_key THEN RETURN to_jsonb(q); END IF;
 IF q.status<>'IN_PROGRESS' OR length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100 THEN RAISE EXCEPTION 'PhiÃªn QC khÃ´ng cÃ²n há»£p lá»‡'; END IF;
 IF p_result NOT IN('PASS','FAIL') OR p_mainboard_status NOT IN('ORIGINAL','OFFICIAL_REPLACED','REPAIRED','UNKNOWN')
   OR p_charger_status NOT IN('ORIGINAL','ORIGINAL_US','COMPATIBLE','MISSING','UNKNOWN') THEN RAISE EXCEPTION 'Káº¿t quáº£ QC khÃ´ng há»£p lá»‡'; END IF;
 IF p_cosmetic_grade IS NOT NULL AND p_cosmetic_grade NOT IN('A','B','C','D') THEN RAISE EXCEPTION 'PhÃ¢n háº¡ng ngoáº¡i hÃ¬nh khÃ´ng há»£p lá»‡'; END IF;
 PERFORM save_qc_checklist(q.id,p_items,p_actor);
 SELECT string_agg(check_key,', ' ORDER BY sort_order) INTO failed_keys FROM qc_check_items WHERE qc_inspection_id=q.id AND requirement='REQUIRED' AND result='FAIL';
 SELECT string_agg(check_key,', ' ORDER BY sort_order) INTO incomplete_keys FROM qc_check_items WHERE qc_inspection_id=q.id AND requirement='REQUIRED' AND result IN('NOT_TESTED','NOT_APPLICABLE');
 IF p_result='PASS' AND (failed_keys IS NOT NULL OR incomplete_keys IS NOT NULL OR p_mainboard_status='REPAIRED' OR p_charger_status='MISSING') THEN RAISE EXCEPTION 'KhÃ´ng thá»ƒ PASS khi checklist báº¯t buá»™c chÆ°a Ä‘áº¡t'; END IF;
 SELECT * INTO l FROM laptops WHERE id=q.laptop_id FOR UPDATE;
 IF l.status<>'waiting_qc' THEN RAISE EXCEPTION 'Tráº¡ng thÃ¡i laptop khÃ´ng khá»›p phiÃªn QC'; END IF;
 UPDATE qc_inspections SET status='COMPLETED',result=p_result,completed_by=p_actor,completed_at=timezone('utc',now()),
  completion_idempotency_key=p_idempotency_key,overall_notes=left(coalesce(p_notes,''),5000),mainboard_status=p_mainboard_status,
  charger_status=p_charger_status,cosmetic_grade=p_cosmetic_grade WHERE id=q.id RETURNING * INTO q;
 PERFORM set_config('app.laptop_transition','on',true);
 UPDATE laptops SET status=CASE WHEN p_result='PASS' THEN 'available' ELSE 'waiting_qc' END,
  available_for_sale_at=CASE WHEN p_result='PASS' THEN coalesce(available_for_sale_at,timezone('utc',now())) ELSE NULL END,
  condition_note=CASE WHEN btrim(coalesce(p_notes,''))<>'' THEN left(p_notes,2000) ELSE condition_note END
 WHERE id=l.id;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
 VALUES('QC_INSPECTION',q.id::text,'UPDATE',jsonb_build_object('result',p_result,'laptop_id',l.id),p_actor);
 RETURN to_jsonb(q);
END $function$;
CREATE OR REPLACE FUNCTION public.prevent_completed_qc_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE parent_status text;
BEGIN
  IF TG_TABLE_NAME='qc_inspections' THEN
    IF TG_OP='DELETE' OR OLD.status IN('COMPLETED','CANCELLED') THEN RAISE EXCEPTION 'Lá»‹ch sá»­ QC Ä‘Ã£ káº¿t thÃºc lÃ  báº¥t biáº¿n'; END IF;
  ELSE
    SELECT status INTO parent_status FROM qc_inspections WHERE id=coalesce(NEW.qc_inspection_id,OLD.qc_inspection_id);
    IF TG_OP='DELETE' OR parent_status<>'IN_PROGRESS' THEN RAISE EXCEPTION 'Checklist cá»§a phiÃªn QC Ä‘Ã£ káº¿t thÃºc lÃ  báº¥t biáº¿n'; END IF;
  END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$;
CREATE OR REPLACE FUNCTION public.next_repair_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE p text:='REP-'||to_char(current_date,'YYYYMMDD')||'-';n int;BEGIN PERFORM pg_advisory_xact_lock(hashtext(p));SELECT coalesce(max(right(repair_code,3)::int),0)+1 INTO n FROM repair_jobs WHERE repair_code LIKE p||'%';RETURN p||lpad(n::text,3,'0');END $function$;
CREATE OR REPLACE FUNCTION public.validate_repair_assignee(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ BEGIN IF p_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM user_profiles WHERE id=p_id AND is_active AND role IN('ADMIN','TECH','TECHNICAL')) THEN RAISE EXCEPTION 'Ká»¹ thuáº­t viÃªn Ä‘Æ°á»£c giao khÃ´ng há»£p lá»‡';END IF;END $function$;
CREATE OR REPLACE FUNCTION public.start_repair_job(p_data jsonb, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE; j repair_jobs%ROWTYPE; sid text:=nullif(p_data->>'source_id',''); assignee uuid:=nullif(p_data->>'assigned_to','')::uuid;
BEGIN
 SELECT * INTO j FROM repair_jobs WHERE idempotency_key=p_idempotency_key; IF FOUND THEN RETURN to_jsonb(j); END IF;
 PERFORM validate_repair_assignee(assignee);
 SELECT * INTO l FROM laptops WHERE id=(p_data->>'laptop_id')::bigint AND is_active FOR UPDATE;
 IF NOT FOUND OR l.status<>'waiting_qc' THEN RAISE EXCEPTION 'Laptop khÃ´ng á»Ÿ tráº¡ng thÃ¡i Ä‘Æ°á»£c táº¡o phiáº¿u sá»­a'; END IF;
 IF p_data->>'source_type'='QC' AND (sid IS NULL OR NOT EXISTS(SELECT 1 FROM qc_inspections WHERE id::text=sid AND laptop_id=l.id AND result='FAIL')) THEN RAISE EXCEPTION 'QC nguá»“n khÃ´ng há»£p lá»‡'; END IF;
 INSERT INTO repair_jobs(repair_code,laptop_id,source_type,source_id,reported_issue,priority,assigned_to,requires_re_qc,created_by,idempotency_key)
 VALUES(next_repair_code(),l.id,p_data->>'source_type',sid,btrim(p_data->>'reported_issue'),coalesce(p_data->>'priority','NORMAL'),assignee,true,p_actor,p_idempotency_key) RETURNING * INTO j;
 PERFORM set_config('app.laptop_transition','on',true); UPDATE laptops SET status='repair',available_for_sale_at=NULL WHERE id=l.id;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('REPAIR_JOB',j.id::text,'CREATE',jsonb_build_object('repair_code',j.repair_code,'laptop_id',l.id),p_actor);
 RETURN to_jsonb(j);
END $function$;
CREATE OR REPLACE FUNCTION public.update_repair_job(p_id uuid, p_data jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE j repair_jobs%ROWTYPE; assignee uuid:=nullif(p_data->>'assigned_to','')::uuid; target text:=coalesce(p_data->>'status','');
BEGIN
 SELECT * INTO j FROM repair_jobs WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR j.status IN('COMPLETED','CANCELLED') THEN RAISE EXCEPTION 'Phiáº¿u sá»­a khÃ´ng cÃ²n Ä‘Æ°á»£c cáº­p nháº­t'; END IF;
 PERFORM validate_repair_assignee(assignee);
 IF NOT ((j.status='OPEN' AND target IN('OPEN','IN_PROGRESS')) OR
         (j.status='IN_PROGRESS' AND target IN('IN_PROGRESS','WAITING_PART','TESTING')) OR
         (j.status='WAITING_PART' AND target IN('WAITING_PART','IN_PROGRESS')) OR
         (j.status='TESTING' AND target IN('TESTING','IN_PROGRESS','WAITING_PART'))) THEN
   RAISE EXCEPTION 'Chuyá»ƒn tráº¡ng thÃ¡i sá»­a chá»¯a khÃ´ng há»£p lá»‡ (% â†’ %)',j.status,target;
 END IF;
 UPDATE repair_jobs SET
   reported_issue=left(coalesce(nullif(btrim(p_data->>'reported_issue'),''),reported_issue),5000),
   status=target,diagnosis=left(coalesce(p_data->>'diagnosis',''),5000),repair_plan=left(coalesce(p_data->>'repair_plan',''),5000),
   priority=coalesce(p_data->>'priority',priority),assigned_to=assignee,
   labor_cost_vnd=coalesce((p_data->>'labor_cost_vnd')::numeric,labor_cost_vnd),notes=left(coalesce(p_data->>'notes',''),5000),
   started_at=CASE WHEN target<>'OPEN' THEN coalesce(started_at,timezone('utc',now())) ELSE started_at END
 WHERE id=p_id RETURNING * INTO j;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('REPAIR_JOB',j.id::text,'UPDATE',jsonb_build_object('status',j.status,'priority',j.priority,'assigned_to',j.assigned_to,'labor_cost_vnd',j.labor_cost_vnd),p_actor);
 RETURN to_jsonb(j);
END $function$;
