CREATE OR REPLACE FUNCTION public.guard_repair_laptop_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status AND (OLD.status='repair' OR NEW.status='repair') AND current_setting('app.repair_transition',true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'Tráº¡ng thÃ¡i sá»­a chá»¯a chá»‰ Ä‘Æ°á»£c Ä‘á»•i qua Repair workflow';END IF;RETURN NEW;END $function$;
CREATE OR REPLACE FUNCTION public.guard_repair_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE s text;BEGIN IF TG_TABLE_NAME='repair_jobs' THEN IF TG_OP='DELETE' OR OLD.status IN('COMPLETED','CANCELLED') THEN RAISE EXCEPTION 'Lá»‹ch sá»­ sá»­a chá»¯a Ä‘Ã£ káº¿t thÃºc lÃ  báº¥t biáº¿n';END IF;ELSE SELECT status INTO s FROM repair_jobs WHERE id=coalesce(NEW.repair_job_id,OLD.repair_job_id);IF TG_OP='DELETE' AND s IN('COMPLETED','CANCELLED') OR TG_OP='UPDATE' AND s IN('COMPLETED','CANCELLED') THEN RAISE EXCEPTION 'Chi tiáº¿t sá»­a chá»¯a Ä‘Ã£ káº¿t thÃºc lÃ  báº¥t biáº¿n';END IF;END IF;RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END $function$;
CREATE OR REPLACE FUNCTION public.complete_repair_job(p_id uuid, p_resolution text, p_outcome text, p_recommended_action text, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE j repair_jobs%ROWTYPE;
BEGIN
 SELECT * INTO j FROM repair_jobs WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'KhÃ´ng tÃ¬m tháº¥y phiáº¿u sá»­a'; END IF;
 IF j.status='COMPLETED' AND j.completion_idempotency_key=p_idempotency_key THEN RETURN to_jsonb(j); END IF;
 IF j.status<>'TESTING' OR btrim(coalesce(p_resolution,''))='' OR length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100 THEN RAISE EXCEPTION 'Chá»‰ cÃ³ thá»ƒ hoÃ n táº¥t phiáº¿u Ä‘ang TESTING'; END IF;
 IF p_outcome NOT IN('REPAIRED','NOT_REPAIRED','PARTIALLY_REPAIRED','NO_FAULT_FOUND') OR p_recommended_action NOT IN('RE_QC','SUPPLIER_RETURN','NO_FURTHER_ACTION','OTHER') THEN RAISE EXCEPTION 'Káº¿t quáº£ sá»­a chá»¯a khÃ´ng há»£p lá»‡'; END IF;
 UPDATE repair_jobs SET status='COMPLETED',resolution=left(p_resolution,5000),outcome=p_outcome,recommended_action=p_recommended_action,
  completed_at=timezone('utc',now()),completion_idempotency_key=p_idempotency_key,
  parts_cost_vnd=(SELECT coalesce(sum(total_cost_vnd),0) FROM repair_parts WHERE repair_job_id=p_id)
 WHERE id=p_id RETURNING * INTO j;
 PERFORM set_config('app.laptop_transition','on',true); UPDATE laptops SET status='waiting_qc',available_for_sale_at=NULL WHERE id=j.laptop_id;
 PERFORM sync_laptop_cost_components(j.laptop_id,p_actor);
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('REPAIR_JOB',j.id::text,'UPDATE',jsonb_build_object('status','COMPLETED','outcome',p_outcome,'recommended_action',p_recommended_action),p_actor);
 RETURN to_jsonb(j);
END $function$;
CREATE OR REPLACE FUNCTION public.next_supplier_return_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE prefix text:='SR-'||to_char(current_date,'YYYYMMDD')||'-';n integer;
BEGIN PERFORM pg_advisory_xact_lock(hashtext(prefix));SELECT coalesce(max(right(return_code,3)::integer),0)+1 INTO n FROM supplier_returns WHERE return_code LIKE prefix||'%';RETURN prefix||lpad(n::text,3,'0');END $function$;
CREATE OR REPLACE FUNCTION public.create_supplier_return(p_data jsonb, p_items jsonb, p_actor text, p_idempotency_key text)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r supplier_returns%ROWTYPE; entry jsonb; l laptops%ROWTYPE; derived_supplier uuid; item_supplier uuid;
BEGIN
 SELECT * INTO r FROM supplier_returns WHERE idempotency_key=p_idempotency_key; IF FOUND THEN RETURN to_jsonb(r); END IF;
 IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100 OR jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Yêu cầu tạo phiếu trả không hợp lệ'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  SELECT * INTO l FROM laptops WHERE id=(entry->>'laptop_id')::bigint AND is_active FOR UPDATE;
  IF NOT FOUND OR l.status NOT IN('waiting_qc','repair','available') OR l.purchase_batch_id IS NULL OR l.source_type='UNKNOWN' THEN RAISE EXCEPTION 'Laptop không đủ điều kiện trả nhà cung cấp'; END IF;
  IF EXISTS(SELECT 1 FROM repair_jobs WHERE laptop_id=l.id AND status NOT IN('COMPLETED','CANCELLED')) THEN RAISE EXCEPTION 'Laptop còn phiếu sửa đang hoạt động; hãy hoàn tất hoặc hủy phiếu sửa trước'; END IF;
  SELECT supplier_id INTO item_supplier FROM purchase_batches WHERE id=l.purchase_batch_id AND active IS TRUE;
  IF item_supplier IS NULL THEN RAISE EXCEPTION 'Không xác định được nhà cung cấp từ lô mua'; END IF;
  IF derived_supplier IS NULL THEN derived_supplier:=item_supplier; ELSIF derived_supplier IS DISTINCT FROM item_supplier THEN RAISE EXCEPTION 'Một phiếu trả chỉ được chứa máy của cùng nhà cung cấp'; END IF;
 END LOOP;
 INSERT INTO supplier_returns(return_code,supplier_id,reason,reason_notes,notes,created_by,idempotency_key)
 VALUES(next_supplier_return_code(),derived_supplier,p_data->>'reason',left(coalesce(p_data->>'reason_notes',''),3000),left(coalesce(p_data->>'notes',''),3000),p_actor,p_idempotency_key) RETURNING * INTO r;
 FOR entry IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  SELECT * INTO l FROM laptops WHERE id=(entry->>'laptop_id')::bigint FOR UPDATE;
  INSERT INTO supplier_return_items(supplier_return_id,laptop_id,repair_job_id,qc_inspection_id,reason,condition_notes,expected_refund_rmb,agreed_refund_rmb,previous_laptop_status)
  VALUES(r.id,l.id,nullif(entry->>'repair_job_id','')::uuid,nullif(entry->>'qc_inspection_id','')::uuid,entry->>'reason',left(coalesce(entry->>'condition_notes',''),3000),nullif(entry->>'expected_refund_rmb','')::numeric,nullif(entry->>'agreed_refund_rmb','')::numeric,l.status);
  PERFORM set_config('app.laptop_transition','on',true);
  UPDATE laptops SET status='supplier_return',available_for_sale_at=NULL WHERE id=l.id;
 END LOOP;
 INSERT INTO supplier_return_events(supplier_return_id,event_type,details,performed_by) VALUES(r.id,'CREATED',jsonb_build_object('item_count',jsonb_array_length(p_items),'supplier_derived',true),p_actor);
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('SUPPLIER_RETURN',r.id::text,'CREATE',jsonb_build_object('event','SUPPLIER_RETURN_CREATED','supplier_id',derived_supplier,'item_count',jsonb_array_length(p_items)),p_actor);
 RETURN to_jsonb(r);
END $function$;CREATE OR REPLACE FUNCTION public.transition_supplier_return(p_id uuid, p_target text, p_data jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r supplier_returns%ROWTYPE; resolution text:=nullif(p_data->>'resolution_type','');
BEGIN
 SELECT * INTO r FROM supplier_returns WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'KhÃ´ng tÃ¬m tháº¥y phiáº¿u tráº£ nhÃ  cung cáº¥p'; END IF;
 PERFORM set_config('app.supplier_return_transition','on',true);
 IF NOT ((r.status='DRAFT' AND p_target IN('APPROVED','CANCELLED')) OR (r.status='APPROVED' AND p_target IN('READY_TO_SHIP','CANCELLED')) OR
  (r.status='READY_TO_SHIP' AND p_target IN('SHIPPED','CANCELLED')) OR (r.status='SHIPPED' AND p_target='SUPPLIER_RECEIVED') OR
  (r.status='SUPPLIER_RECEIVED' AND p_target IN('WAITING_REFUND','WAITING_REPLACEMENT','REJECTED')) OR
  (r.status IN('REFUNDED','REPLACED','REJECTED') AND p_target='CLOSED')) THEN RAISE EXCEPTION 'Chuyá»ƒn tráº¡ng thÃ¡i tráº£ NCC khÃ´ng há»£p lá»‡'; END IF;
 IF p_target='SHIPPED' AND (btrim(coalesce(p_data->>'carrier',r.return_carrier,''))='' OR btrim(coalesce(p_data->>'tracking_number',r.return_tracking_number,''))='') THEN RAISE EXCEPTION 'Cáº§n Ä‘Æ¡n vá»‹ váº­n chuyá»ƒn vÃ  tracking'; END IF;
 UPDATE supplier_returns SET status=p_target,resolution_type=coalesce(resolution,resolution_type),
  return_carrier=left(coalesce(nullif(p_data->>'carrier',''),return_carrier),160),return_tracking_number=left(coalesce(nullif(p_data->>'tracking_number',''),return_tracking_number),200),
  approved_by=CASE WHEN p_target='APPROVED' THEN p_actor ELSE approved_by END,approved_at=CASE WHEN p_target='APPROVED' THEN timezone('utc',now()) ELSE approved_at END,
  shipped_at=CASE WHEN p_target='SHIPPED' THEN timezone('utc',now()) ELSE shipped_at END,supplier_received_at=CASE WHEN p_target='SUPPLIER_RECEIVED' THEN timezone('utc',now()) ELSE supplier_received_at END,
  closed_at=CASE WHEN p_target IN('CLOSED','CANCELLED') THEN timezone('utc',now()) ELSE closed_at END WHERE id=r.id RETURNING * INTO r;
 IF p_target IN('APPROVED','READY_TO_SHIP','SHIPPED','SUPPLIER_RECEIVED','WAITING_REFUND','WAITING_REPLACEMENT') THEN
  PERFORM set_config('app.laptop_transition','on',true); UPDATE laptops SET status='supplier_return',available_for_sale_at=NULL WHERE id IN(SELECT laptop_id FROM supplier_return_items WHERE supplier_return_id=r.id);
 END IF;
 IF p_target='CANCELLED' THEN
  PERFORM set_config('app.laptop_transition','on',true); UPDATE laptops l SET status=coalesce(i.previous_laptop_status,'waiting_qc') FROM supplier_return_items i WHERE i.supplier_return_id=r.id AND i.laptop_id=l.id;
  UPDATE supplier_return_items SET status='CANCELLED' WHERE supplier_return_id=r.id;
 END IF;
 IF p_target='SHIPPED' THEN UPDATE supplier_return_items SET status='SHIPPED' WHERE supplier_return_id=r.id; END IF;
 IF p_target='SUPPLIER_RECEIVED' THEN UPDATE supplier_return_items SET status='SUPPLIER_RECEIVED' WHERE supplier_return_id=r.id; END IF;
 INSERT INTO supplier_return_events(supplier_return_id,event_type,details,performed_by) VALUES(r.id,p_target,jsonb_build_object('resolution_type',r.resolution_type),p_actor);
 RETURN to_jsonb(r);
END $function$;
CREATE OR REPLACE FUNCTION public.record_supplier_refund(p_return_id uuid, p_amount_rmb numeric, p_exchange_rate numeric, p_method text, p_reference text, p_received_at timestamp with time zone, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r supplier_returns%ROWTYPE;refund supplier_refunds%ROWTYPE;limit_amount numeric;refunded numeric;
BEGIN
 SELECT * INTO refund FROM supplier_refunds WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(refund);END IF;
 SELECT * INTO r FROM supplier_returns WHERE id=p_return_id FOR UPDATE;IF NOT FOUND OR r.status NOT IN('WAITING_REFUND','PARTIALLY_RESOLVED') THEN RAISE EXCEPTION 'Phiáº¿u tráº£ chÆ°a á»Ÿ tráº¡ng thÃ¡i nháº­n hoÃ n tiá»n';END IF;
 SELECT coalesce(sum(coalesce(agreed_refund_rmb,expected_refund_rmb)),0) INTO limit_amount FROM supplier_return_items WHERE supplier_return_id=r.id AND status<>'CANCELLED';
 SELECT coalesce(sum(amount_rmb),0) INTO refunded FROM supplier_refunds WHERE supplier_return_id=r.id;
 IF p_amount_rmb<=0 OR limit_amount<=0 OR p_amount_rmb>limit_amount-refunded THEN RAISE EXCEPTION 'Sá»‘ tiá»n hoÃ n vÆ°á»£t sá»‘ cÃ²n pháº£i nháº­n';END IF;
 IF p_exchange_rate IS NOT NULL AND p_exchange_rate<=0 THEN RAISE EXCEPTION 'Tá»· giÃ¡ khÃ´ng há»£p lá»‡';END IF;
 INSERT INTO supplier_refunds(supplier_id,supplier_return_id,amount_rmb,amount_vnd,exchange_rate,refund_method,reference,received_at,idempotency_key,created_by)
 VALUES(r.supplier_id,r.id,p_amount_rmb,CASE WHEN p_exchange_rate IS NULL THEN NULL ELSE round(p_amount_rmb*p_exchange_rate,2) END,p_exchange_rate,p_method,left(coalesce(p_reference,''),300),coalesce(p_received_at,timezone('utc',now())),p_idempotency_key,p_actor) RETURNING * INTO refund;
 refunded:=refunded+p_amount_rmb;
 UPDATE supplier_returns SET status=CASE WHEN refunded>=limit_amount THEN 'REFUNDED' ELSE 'PARTIALLY_RESOLVED' END WHERE id=r.id;
 IF refunded>=limit_amount THEN UPDATE supplier_return_items SET status='REFUNDED' WHERE supplier_return_id=r.id AND status<>'CANCELLED';END IF;
 INSERT INTO supplier_return_events(supplier_return_id,event_type,details,performed_by) VALUES(r.id,'REFUND_RECEIVED',jsonb_build_object('amount_rmb',p_amount_rmb,'refunded_rmb',refunded,'remaining_rmb',greatest(limit_amount-refunded,0)),p_actor);
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('SUPPLIER_REFUND',refund.id::text,'CREATE',jsonb_build_object('supplier_return_id',r.id,'amount_rmb',p_amount_rmb),p_actor);
 RETURN to_jsonb(refund);
EXCEPTION WHEN unique_violation THEN SELECT * INTO refund FROM supplier_refunds WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(refund);END IF;RAISE;
END $function$;
CREATE OR REPLACE FUNCTION public.prevent_supplier_refund_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND current_setting('app.financial_account_link',true)='on' AND OLD.account_id IS NULL AND NEW.account_id IS NOT NULL
   AND (to_jsonb(NEW)-'account_id')=(to_jsonb(OLD)-'account_id') THEN RETURN NEW;END IF;
 RAISE EXCEPTION 'HoÃ n tiá»n nhÃ  cung cáº¥p lÃ  ledger báº¥t biáº¿n';
END $function$;
CREATE OR REPLACE FUNCTION public.guard_supplier_return_laptop_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status AND (OLD.status IN('supplier_return_pending','supplier_returned') OR NEW.status IN('supplier_return_pending','supplier_returned')) AND current_setting('app.supplier_return_transition',true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'Tráº¡ng thÃ¡i tráº£ nhÃ  cung cáº¥p chá»‰ Ä‘Æ°á»£c Ä‘á»•i qua Supplier Return workflow';END IF;RETURN NEW;END $function$;
CREATE OR REPLACE FUNCTION public.guard_closed_supplier_return_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE parent_status text;
BEGIN
 IF TG_TABLE_NAME='supplier_returns' THEN
  IF TG_OP='DELETE' OR OLD.status IN('CLOSED','CANCELLED') THEN RAISE EXCEPTION 'Lá»‹ch sá»­ phiáº¿u tráº£ Ä‘Ã£ Ä‘Ã³ng lÃ  báº¥t biáº¿n';END IF;
 ELSE
  SELECT status INTO parent_status FROM supplier_returns WHERE id=coalesce(NEW.supplier_return_id,OLD.supplier_return_id);
  IF (TG_OP='DELETE' OR parent_status IN('CLOSED','CANCELLED'))
     AND current_setting('app.supplier_return_transition',true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'Chi tiáº¿t phiáº¿u tráº£ Ä‘Ã£ Ä‘Ã³ng lÃ  báº¥t biáº¿n';END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$;
CREATE OR REPLACE FUNCTION public.sync_laptop_cost_components(p_laptop_id bigint, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE; r repair_jobs%ROWTYPE; repair_count integer:=0;
BEGIN
  SELECT * INTO l FROM laptops WHERE id=p_laptop_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'KhÃ´ng tÃ¬m tháº¥y laptop'; END IF;
  FOR r IN SELECT * FROM repair_jobs WHERE laptop_id=l.id AND status='COMPLETED' LOOP
    INSERT INTO laptop_cost_components(laptop_id,cost_type,amount_vnd,source_type,source_id,description,occurred_at,created_by)
    VALUES(l.id,'REPAIR',round(r.total_cost_vnd,0),'REPAIR_JOB',r.id::text,'Chi phÃ­ '||r.repair_code,coalesce(r.completed_at,r.updated_at),p_actor)
    ON CONFLICT(laptop_id,source_type,source_id,cost_type) WHERE source_id IS NOT NULL AND voided_at IS NULL
    DO UPDATE SET amount_vnd=excluded.amount_vnd,description=excluded.description;
    repair_count:=repair_count+1;
  END LOOP;
  RETURN jsonb_build_object('laptop_id',l.id,'repair_jobs_synced',repair_count);
END $function$;
CREATE OR REPLACE FUNCTION public.add_manual_laptop_cost(p_laptop_id bigint, p_cost_type text, p_amount_vnd numeric, p_description text, p_occurred_at timestamp with time zone, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE c laptop_cost_components%ROWTYPE;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM laptops WHERE id=p_laptop_id) THEN RAISE EXCEPTION 'KhÃ´ng tÃ¬m tháº¥y laptop';END IF;
 IF p_cost_type NOT IN('RAM_UPGRADE','SSD_UPGRADE','ACCESSORY','CLEANING','OTHER') OR p_amount_vnd<=0 OR p_amount_vnd<>round(p_amount_vnd,0) OR btrim(coalesce(p_description,''))='' OR length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100 THEN RAISE EXCEPTION 'Chi phÃ­ thá»§ cÃ´ng khÃ´ng há»£p lá»‡';END IF;
 SELECT * INTO c FROM laptop_cost_components WHERE laptop_id=p_laptop_id AND source_type='MANUAL' AND source_id=p_idempotency_key AND cost_type=p_cost_type AND voided_at IS NULL;IF FOUND THEN RETURN to_jsonb(c);END IF;
 INSERT INTO laptop_cost_components(laptop_id,cost_type,amount_vnd,source_type,source_id,description,occurred_at,created_by) VALUES(p_laptop_id,p_cost_type,p_amount_vnd,'MANUAL',p_idempotency_key,left(p_description,1000),coalesce(p_occurred_at,timezone('utc',now())),p_actor) RETURNING * INTO c;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('LAPTOP_COST',c.id::text,'CREATE',jsonb_build_object('event','COST_COMPONENT_ADDED','laptop_id',p_laptop_id,'cost_type',p_cost_type,'amount_vnd',p_amount_vnd),p_actor);RETURN to_jsonb(c);
END $function$;
CREATE OR REPLACE FUNCTION public.void_manual_laptop_cost(p_id uuid, p_reason text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE c laptop_cost_components%ROWTYPE;
BEGIN IF btrim(coalesce(p_reason,''))='' THEN RAISE EXCEPTION 'Cáº§n nháº­p lÃ½ do void chi phÃ­';END IF;PERFORM set_config('app.cost_component_void','on',true);UPDATE laptop_cost_components SET voided_at=timezone('utc',now()),voided_by=p_actor,void_reason=left(btrim(p_reason),1000) WHERE id=p_id AND source_type='MANUAL' AND voided_at IS NULL RETURNING * INTO c;IF NOT FOUND THEN RAISE EXCEPTION 'Chá»‰ cÃ³ thá»ƒ void chi phÃ­ thá»§ cÃ´ng Ä‘ang hoáº¡t Ä‘á»™ng';END IF;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('LAPTOP_COST',c.id::text,'UPDATE',jsonb_build_object('event','COST_COMPONENT_VOIDED','reason',p_reason),p_actor);RETURN to_jsonb(c);END $function$;
CREATE OR REPLACE FUNCTION public.snapshot_order_cost()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE cost laptop_landed_costs%ROWTYPE;direct_cost numeric;sale_vnd numeric;
BEGIN
 IF NEW.order_status IN('prepared','shipping','done') AND NEW.cost_snapshotted_at IS NULL AND NEW.laptop_id IS NOT NULL THEN
  PERFORM sync_laptop_cost_components(NEW.laptop_id,'SYSTEM');SELECT * INTO cost FROM laptop_landed_costs WHERE laptop_id=NEW.laptop_id;
  sale_vnd:=coalesce(NEW.sale_price,0)*1000000;direct_cost:=coalesce(NEW.credit_card_fee,0)*1000000;
  NEW.cost_snapshot_vnd:=cost.landed_cost_vnd;NEW.gross_profit_snapshot_vnd:=sale_vnd-cost.landed_cost_vnd;NEW.direct_cost_snapshot_vnd:=direct_cost;NEW.net_contribution_snapshot_vnd:=sale_vnd-cost.landed_cost_vnd-direct_cost;NEW.cost_snapshot_status:=cost.cost_status;NEW.cost_snapshot_reasons:=to_jsonb(cost.reasons);NEW.cost_snapshotted_at:=timezone('utc',now());NEW.profit_vnd:=round((sale_vnd-cost.landed_cost_vnd)/1000000,4);
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('ORDER',coalesce(NEW.id::text,'pending'),'UPDATE',jsonb_build_object('event','COST_SNAPSHOT_CREATED','laptop_id',NEW.laptop_id,'cost_snapshot_vnd',NEW.cost_snapshot_vnd,'cost_status',NEW.cost_snapshot_status),'SYSTEM');
 END IF;RETURN NEW;
END $function$;
