CREATE OR REPLACE FUNCTION public.sync_repair_cost_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.status='COMPLETED' AND OLD.status IS DISTINCT FROM NEW.status THEN
    PERFORM public.sync_laptop_cost_components(
      NEW.laptop_id,
      coalesce(nullif(NEW.created_by,''),'SYSTEM')
    );
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.guard_laptop_cost_component_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Lá»‹ch sá»­ cáº¥u pháº§n giÃ¡ vá»‘n lÃ  báº¥t biáº¿n';END IF;
 IF OLD.source_type<>'MANUAL' AND current_setting('app.cost_component_sync',true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'Cáº¥u pháº§n giÃ¡ vá»‘n há»‡ thá»‘ng lÃ  báº¥t biáº¿n';END IF;
 IF OLD.source_type<>'MANUAL' THEN RETURN NEW;END IF;
 IF current_setting('app.cost_component_void',true) IS DISTINCT FROM 'on' OR NEW.laptop_id IS DISTINCT FROM OLD.laptop_id OR NEW.cost_type IS DISTINCT FROM OLD.cost_type OR NEW.amount_vnd IS DISTINCT FROM OLD.amount_vnd OR NEW.source_type IS DISTINCT FROM OLD.source_type OR NEW.source_id IS DISTINCT FROM OLD.source_id OR NEW.description IS DISTINCT FROM OLD.description OR NEW.occurred_at IS DISTINCT FROM OLD.occurred_at OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN RAISE EXCEPTION 'Chi phÃ­ thá»§ cÃ´ng chá»‰ Ä‘Æ°á»£c void qua workflow giÃ¡ vá»‘n';END IF;
 RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.get_management_dashboard()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
WITH available AS (
 SELECT l.id,l.serial,l.name,l.location,l.retail_price_vnd,l.available_for_sale_at,c.landed_cost_vnd,c.cost_status,
   CASE WHEN l.available_for_sale_at IS NULL THEN NULL
        ELSE greatest(floor(extract(epoch FROM(now()-l.available_for_sale_at))/86400),0)::integer END age_days
 FROM laptops l LEFT JOIN laptop_landed_costs c ON c.laptop_id=l.id
 WHERE l.is_active IS TRUE AND l.status='available'
), aging AS (
 SELECT bucket_key,bucket_label,sort_order,count(*)::integer units,
   coalesce(sum(landed_cost_vnd) FILTER(WHERE cost_status='COMPLETE'),0)::numeric(18,2) landed_cost_value,
   round(avg(age_days),1) average_age
 FROM available a CROSS JOIN LATERAL(VALUES(
   CASE WHEN age_days<=7 THEN '0_7' WHEN age_days<=15 THEN '8_15' WHEN age_days<=30 THEN '16_30'
        WHEN age_days<=60 THEN '31_60' WHEN age_days<=90 THEN '61_90' ELSE '90_plus' END,
   CASE WHEN age_days<=7 THEN '0â€“7 ngÃ y' WHEN age_days<=15 THEN '8â€“15 ngÃ y' WHEN age_days<=30 THEN '16â€“30 ngÃ y'
        WHEN age_days<=60 THEN '31â€“60 ngÃ y' WHEN age_days<=90 THEN '61â€“90 ngÃ y' ELSE '90+ ngÃ y' END,
   CASE WHEN age_days<=7 THEN 1 WHEN age_days<=15 THEN 2 WHEN age_days<=30 THEN 3
        WHEN age_days<=60 THEN 4 WHEN age_days<=90 THEN 5 ELSE 6 END
 )) b(bucket_key,bucket_label,sort_order) WHERE age_days IS NOT NULL GROUP BY bucket_key,bucket_label,sort_order
), states AS (
 SELECT status state,count(*)::integer units FROM laptops WHERE is_active IS TRUE GROUP BY status
), active_repairs AS (
 SELECT r.*,c.landed_cost_vnd,c.cost_status FROM repair_jobs r LEFT JOIN laptop_landed_costs c ON c.laptop_id=r.laptop_id
 WHERE r.status NOT IN('COMPLETED','CANCELLED')
), active_returns AS (
 SELECT r.id,r.status,ri.laptop_id,coalesce(ri.agreed_refund_rmb,ri.expected_refund_rmb,0) refundable_rmb,
   c.landed_cost_vnd,c.cost_status
 FROM supplier_returns r JOIN supplier_return_items ri ON ri.supplier_return_id=r.id
 LEFT JOIN laptop_landed_costs c ON c.laptop_id=ri.laptop_id
 WHERE r.status NOT IN('REFUNDED','REPLACED','REJECTED','CLOSED','CANCELLED')
), refunds AS (SELECT supplier_return_id,sum(amount_rmb) amount_rmb FROM supplier_refunds GROUP BY supplier_return_id)
SELECT jsonb_build_object(
 'generated_at',timezone('utc',now()),'thresholds',jsonb_build_object('warning_days',30,'critical_days',60),
 'available',jsonb_build_object('units',(SELECT count(*) FROM available),
   'cost_complete',(SELECT count(*) FROM available WHERE cost_status='COMPLETE'),
   'cost_incomplete',(SELECT count(*) FROM available WHERE cost_status='INCOMPLETE'),
   'legacy',0,'missing_aging_timestamp',(SELECT count(*) FROM available WHERE available_for_sale_at IS NULL),
   'known_inventory_cost_vnd',(SELECT coalesce(sum(landed_cost_vnd),0) FROM available WHERE cost_status='COMPLETE')),
 'aging',coalesce((SELECT jsonb_agg(to_jsonb(aging) ORDER BY sort_order) FROM aging),'[]'::jsonb),
 'state_summary',(SELECT coalesce(jsonb_object_agg(state,units),'{}'::jsonb) FROM states),
 'transit',jsonb_build_object('units',(SELECT count(*) FROM laptops WHERE status='in_transit'),
   'purchase_value_vnd',(SELECT coalesce(sum((purchase_price_rmb+shipping_rmb)*purchase_exchange_rate),0) FROM laptops WHERE status='in_transit'),
   'by_stage',jsonb_build_object('IN_TRANSIT',(SELECT count(*) FROM laptops WHERE status='in_transit'))),
 'qc',jsonb_build_object('waiting_qc',jsonb_build_object('units',(SELECT count(*) FROM laptops WHERE status='waiting_qc'),'oldest_age',0),
   'qc_in_progress',jsonb_build_object('units',(SELECT count(*) FROM qc_inspections WHERE status='IN_PROGRESS'),'oldest_age',0),
   'qc_failed',jsonb_build_object('units',0,'oldest_age',0),
   'known_cost_vnd',(SELECT coalesce(sum(c.landed_cost_vnd),0) FROM laptops l JOIN laptop_landed_costs c ON c.laptop_id=l.id WHERE l.status='waiting_qc' AND c.cost_status='COMPLETE')),
 'repairs',jsonb_build_object('active_jobs',(SELECT count(*) FROM active_repairs),
   'waiting_parts',(SELECT count(*) FROM active_repairs WHERE status='WAITING_PART'),'oldest_age',0,
   'accumulated_cost_vnd',(SELECT coalesce(sum(total_cost_vnd),0) FROM active_repairs),
   'known_laptop_cost_vnd',(SELECT coalesce(sum(landed_cost_vnd),0) FROM active_repairs WHERE cost_status='COMPLETE')),
 'supplier_returns',jsonb_build_object('pending',(SELECT count(DISTINCT id) FROM active_returns),
   'shipped',(SELECT count(DISTINCT id) FROM active_returns WHERE status IN('SHIPPED','SUPPLIER_RECEIVED')),
   'waiting_refund',(SELECT count(DISTINCT id) FROM active_returns WHERE status IN('WAITING_REFUND','PARTIALLY_RESOLVED')),
   'waiting_replacement',(SELECT count(DISTINCT id) FROM active_returns WHERE status='WAITING_REPLACEMENT'),
   'known_cost_exposure_vnd',(SELECT coalesce(sum(landed_cost_vnd),0) FROM active_returns WHERE cost_status='COMPLETE'),
   'refund_pending_rmb',(SELECT coalesce(sum(greatest(x.refundable-coalesce(rf.amount_rmb,0),0)),0)
      FROM(SELECT id,sum(refundable_rmb) refundable FROM active_returns GROUP BY id)x LEFT JOIN refunds rf ON rf.supplier_return_id=x.id)),
 'slow_moving',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY age_days DESC,laptop_id) FROM(
   SELECT id laptop_id,serial,name model,location,age_days,landed_cost_vnd,cost_status,
    round(coalesce(retail_price_vnd,0)*1000000,0) selling_price_vnd,
    CASE WHEN cost_status='COMPLETE' THEN round(coalesce(retail_price_vnd,0)*1000000-landed_cost_vnd,0) END gross_margin_potential_vnd
   FROM available WHERE age_days>=30 ORDER BY age_days DESC,id LIMIT 25)x),'[]'::jsonb)
)
$function$;
CREATE OR REPLACE FUNCTION public.assert_cash_account(p_id uuid, p_currency text, p_occurred_at timestamp with time zone)
 RETURNS cash_accounts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE a cash_accounts%ROWTYPE;
BEGIN SELECT * INTO a FROM cash_accounts WHERE id=p_id AND is_active FOR UPDATE;IF NOT FOUND OR a.currency<>p_currency THEN RAISE EXCEPTION 'TÃ i khoáº£n tiá»n khÃ´ng tá»“n táº¡i hoáº·c sai loáº¡i tiá»n';END IF;IF p_occurred_at<a.opening_balance_at THEN RAISE EXCEPTION 'Giao dá»‹ch khÃ´ng Ä‘Æ°á»£c trÆ°á»›c thá»i Ä‘iá»ƒm opening balance';END IF;RETURN a;END $function$;
CREATE OR REPLACE FUNCTION public.create_cash_account(p_data jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE a cash_accounts%ROWTYPE;
BEGIN IF coalesce((p_data->>'opening_balance')::numeric,0)<0 OR (p_data->>'account_type') NOT IN('CASH','BANK','WECHAT','ALIPAY','OTHER') OR (p_data->>'currency') NOT IN('VND','CNY') THEN RAISE EXCEPTION 'ThÃ´ng tin tÃ i khoáº£n khÃ´ng há»£p lá»‡';END IF;
 INSERT INTO cash_accounts(code,name,account_type,currency,opening_balance,opening_balance_at,created_by) VALUES(upper(btrim(p_data->>'code')),btrim(p_data->>'name'),p_data->>'account_type',p_data->>'currency',coalesce((p_data->>'opening_balance')::numeric,0),(p_data->>'opening_balance_at')::timestamptz,p_actor) RETURNING * INTO a;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('CASH_ACCOUNT',a.id::text,'CREATE',jsonb_build_object('event','CASH_ACCOUNT_CREATED','code',a.code,'currency',a.currency,'opening_balance',a.opening_balance),p_actor);RETURN to_jsonb(a);END $function$;
CREATE OR REPLACE FUNCTION public.post_manual_account_transaction(p_account_id uuid, p_direction text, p_amount numeric, p_description text, p_occurred_at timestamp with time zone, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE a cash_accounts%ROWTYPE;t account_transactions%ROWTYPE;
BEGIN SELECT * INTO t FROM account_transactions WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(t);END IF;IF p_direction NOT IN('IN','OUT') OR p_amount<=0 OR btrim(coalesce(p_description,''))='' THEN RAISE EXCEPTION 'Giao dá»‹ch thá»§ cÃ´ng khÃ´ng há»£p lá»‡';END IF;a:=assert_cash_account(p_account_id,(SELECT currency FROM cash_accounts WHERE id=p_account_id),p_occurred_at);
 INSERT INTO account_transactions(account_id,direction,amount,currency,reference_type,reference_id,transaction_type,occurred_at,description,idempotency_key,created_by) VALUES(a.id,p_direction,p_amount,a.currency,'MANUAL',p_idempotency_key,CASE WHEN p_direction='IN' THEN 'MANUAL_IN' ELSE 'MANUAL_OUT' END,p_occurred_at,left(p_description,1000),p_idempotency_key,p_actor) RETURNING * INTO t;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('ACCOUNT_TRANSACTION',t.id::text,'CREATE',jsonb_build_object('event','ACCOUNT_TRANSACTION_POSTED','account_id',a.id,'direction',p_direction,'amount',p_amount,'currency',a.currency),p_actor);RETURN to_jsonb(t);END $function$;
CREATE OR REPLACE FUNCTION public.transfer_cash_accounts(p_source uuid, p_destination uuid, p_amount numeric, p_occurred_at timestamp with time zone, p_description text, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE src cash_accounts%ROWTYPE;dst cash_accounts%ROWTYPE;gid uuid:=gen_random_uuid();existing account_transactions%ROWTYPE;
BEGIN SELECT * INTO existing FROM account_transactions WHERE idempotency_key=p_idempotency_key||'-OUT';IF FOUND THEN RETURN jsonb_build_object('transfer_group_id',existing.transfer_group_id);END IF;IF p_source=p_destination OR p_amount<=0 OR btrim(coalesce(p_description,''))='' THEN RAISE EXCEPTION 'Transfer khÃ´ng há»£p lá»‡';END IF;
 src:=assert_cash_account(p_source,(SELECT currency FROM cash_accounts WHERE id=p_source),p_occurred_at);dst:=assert_cash_account(p_destination,src.currency,p_occurred_at);
 INSERT INTO account_transactions(account_id,direction,amount,currency,reference_type,reference_id,transaction_type,occurred_at,description,idempotency_key,transfer_group_id,created_by) VALUES
 (src.id,'OUT',p_amount,src.currency,'TRANSFER',gid::text,'TRANSFER_OUT',p_occurred_at,left(p_description,1000),p_idempotency_key||'-OUT',gid,p_actor),
 (dst.id,'IN',p_amount,dst.currency,'TRANSFER',gid::text,'TRANSFER_IN',p_occurred_at,left(p_description,1000),p_idempotency_key||'-IN',gid,p_actor);
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('ACCOUNT_TRANSFER',gid::text,'CREATE',jsonb_build_object('event','ACCOUNT_TRANSFER','source',src.id,'destination',dst.id,'amount',p_amount,'currency',src.currency),p_actor);RETURN jsonb_build_object('transfer_group_id',gid);END $function$;
CREATE OR REPLACE FUNCTION public.reconcile_cash_account(p_account_id uuid, p_actual numeric, p_reconciled_at timestamp with time zone, p_notes text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a cash_accounts%ROWTYPE;recorded numeric(20,2);r account_reconciliations%ROWTYPE;
BEGIN
 SELECT * INTO a FROM cash_accounts WHERE id=p_account_id AND is_active FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'KhÃ´ng tÃ¬m tháº¥y tÃ i khoáº£n';END IF;
 IF p_actual IS NULL OR p_reconciled_at IS NULL THEN RAISE EXCEPTION 'ThÃ´ng tin Ä‘á»‘i soÃ¡t khÃ´ng há»£p lá»‡';END IF;
 SELECT (a.opening_balance+coalesce(sum(CASE WHEN direction='IN' THEN amount ELSE -amount END),0))::numeric(20,2)
 INTO recorded FROM account_transactions WHERE account_id=a.id AND occurred_at>=a.opening_balance_at;
 INSERT INTO account_reconciliations(account_id,recorded_balance,actual_balance,reconciled_at,notes,created_by)
 VALUES(a.id,recorded,p_actual,p_reconciled_at,left(coalesce(p_notes,''),2000),p_actor) RETURNING * INTO r;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES
 ('CASH_ACCOUNT',a.id::text,'UPDATE',jsonb_build_object('event','ACCOUNT_RECONCILED','recorded',recorded,'actual',p_actual,'difference',r.difference),p_actor);
 RETURN to_jsonb(r);
END $function$;
CREATE OR REPLACE FUNCTION public.record_order_payment_with_account(p_order_id bigint, p_amount numeric, p_payment_type text, p_payment_method text, p_payment_date date, p_reference_code text, p_note text, p_recorded_by text, p_account_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE result jsonb;p payments%ROWTYPE;a cash_accounts%ROWTYPE;t account_transactions%ROWTYPE;occurred timestamptz:=coalesce(p_payment_date,current_date)::timestamptz;
BEGIN
 IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 90 THEN RAISE EXCEPTION 'Idempotency key khÃ´ng há»£p lá»‡';END IF;
 SELECT * INTO p FROM payments WHERE idempotency_key=p_idempotency_key;
 IF FOUND THEN
   IF p.account_id IS DISTINCT FROM p_account_id THEN RAISE EXCEPTION 'Idempotency key Ä‘Ã£ dÃ¹ng cho tÃ i khoáº£n khÃ¡c';END IF;
   SELECT jsonb_build_object('payment',to_jsonb(p),'order',to_jsonb(o),'account_transaction',to_jsonb(x)) INTO result
   FROM orders o LEFT JOIN account_transactions x ON x.reference_type='PAYMENT' AND x.reference_id=p.id::text WHERE o.id=p.order_id;
   RETURN result;
 END IF;
 a:=assert_cash_account(p_account_id,'VND',occurred);
 result:=record_order_payment(p_order_id,p_amount,p_payment_type,p_payment_method,coalesce(p_payment_date,current_date),p_reference_code,p_note,p_recorded_by);
 p:=jsonb_populate_record(NULL::payments,result->'payment');
 UPDATE payments SET account_id=a.id,idempotency_key=p_idempotency_key WHERE id=p.id RETURNING * INTO p;
 INSERT INTO account_transactions(account_id,direction,amount,currency,reference_type,reference_id,transaction_type,occurred_at,description,idempotency_key,created_by)
 VALUES(a.id,CASE WHEN p_payment_type='refund' THEN 'OUT' ELSE 'IN' END,round(p_amount*1000000,0),'VND','PAYMENT',p.id::text,'CUSTOMER_PAYMENT',occurred,left(coalesce(p_note,'Thanh toÃ¡n Ä‘Æ¡n #'||p_order_id),1000),p_idempotency_key||'-CASH',p_recorded_by) RETURNING * INTO t;
 RETURN jsonb_set(jsonb_set(result,'{payment}',to_jsonb(p)),'{account_transaction}',to_jsonb(t));
END $function$;
CREATE OR REPLACE FUNCTION public.create_cod_receivable(p_order_id bigint, p_carrier text, p_tracking text, p_expected_settlement_at timestamp with time zone, p_notes text, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE o orders%ROWTYPE;c cod_receivables%ROWTYPE;expected numeric;
BEGIN SELECT * INTO c FROM cod_receivables WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(c);END IF;SELECT * INTO o FROM orders WHERE id=p_order_id AND is_active FOR UPDATE;IF NOT FOUND OR coalesce(o.cod_amount,0)<=0 THEN RAISE EXCEPTION 'ÄÆ¡n hÃ ng khÃ´ng cÃ³ COD há»£p lá»‡';END IF;expected:=round(least(o.cod_amount,o.debt_amount)*1000000,0);IF expected<=0 THEN RAISE EXCEPTION 'ÄÆ¡n hÃ ng khÃ´ng cÃ²n khoáº£n COD pháº£i thu';END IF;
 INSERT INTO cod_receivables(order_id,carrier,tracking_number,expected_cod_amount_vnd,shipped_at,expected_settlement_at,notes,idempotency_key,created_by) VALUES(o.id,left(coalesce(p_carrier,''),160),left(coalesce(p_tracking,o.tracking_code,''),200),expected,CASE WHEN o.order_status IN('shipping','done') THEN now() END,p_expected_settlement_at,left(coalesce(p_notes,''),2000),p_idempotency_key,p_actor) RETURNING * INTO c;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('COD_RECEIVABLE',c.id::text,'CREATE',jsonb_build_object('event','COD_CREATED','order_id',o.id,'expected_vnd',expected),p_actor);RETURN to_jsonb(c);END $function$;
CREATE OR REPLACE FUNCTION public.transition_cod_receivable(p_id uuid, p_target text, p_expected_settlement_at timestamp with time zone, p_notes text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c cod_receivables%ROWTYPE;result jsonb;
BEGIN
 SELECT * INTO c FROM cod_receivables WHERE id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'KhÃ´ng tÃ¬m tháº¥y COD';END IF;
 IF p_target='DELIVERED' AND c.status='PENDING_DELIVERY' THEN
   result:=record_order_payment(c.order_id,c.expected_cod_amount_vnd/1000000,'cod','cod',current_date,c.tracking_number,'COD Ä‘Ã£ giao - chuyá»ƒn nghÄ©a vá»¥ pháº£i thu sang Ä‘Æ¡n vá»‹ váº­n chuyá»ƒn',p_actor);
   UPDATE cod_receivables SET status='DELIVERED',delivered_at=now(),expected_settlement_at=coalesce(p_expected_settlement_at,expected_settlement_at),notes=left(coalesce(p_notes,notes),2000) WHERE id=c.id RETURNING * INTO c;
 ELSIF p_target='WAITING_SETTLEMENT' AND c.status='DELIVERED' THEN
   UPDATE cod_receivables SET status='WAITING_SETTLEMENT',expected_settlement_at=coalesce(p_expected_settlement_at,expected_settlement_at),notes=left(coalesce(p_notes,notes),2000) WHERE id=c.id RETURNING * INTO c;
 ELSIF p_target='DISPUTED' AND c.status IN('DELIVERED','WAITING_SETTLEMENT','PARTIALLY_SETTLED') THEN
   UPDATE cod_receivables SET status='DISPUTED',notes=left(coalesce(p_notes,notes),2000) WHERE id=c.id RETURNING * INTO c;
 ELSIF p_target IN('RETURNED','CANCELLED') AND c.status='PENDING_DELIVERY' THEN
   UPDATE cod_receivables SET status=p_target,notes=left(coalesce(p_notes,notes),2000) WHERE id=c.id RETURNING * INTO c;
 ELSE RAISE EXCEPTION 'Chuyá»ƒn tráº¡ng thÃ¡i COD khÃ´ng há»£p lá»‡';END IF;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('COD_RECEIVABLE',c.id::text,'UPDATE',jsonb_build_object('event','COD_'||p_target,'status',p_target),p_actor);
 RETURN to_jsonb(c);
END $function$;
CREATE OR REPLACE FUNCTION public.record_cod_settlement(p_cod_id uuid, p_amount_vnd numeric, p_account_id uuid, p_reference text, p_settled_at timestamp with time zone, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c cod_receivables%ROWTYPE;
  s cod_settlements%ROWTYPE;
  a cash_accounts%ROWTYPE;
  paid numeric;
  remaining numeric;
  t account_transactions%ROWTYPE;
BEGIN
  SELECT * INTO s FROM cod_settlements WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN RETURN to_jsonb(s); END IF;

  SELECT * INTO c FROM cod_receivables WHERE id = p_cod_id FOR UPDATE;
  IF NOT FOUND OR c.status NOT IN ('WAITING_SETTLEMENT', 'PARTIALLY_SETTLED', 'DISPUTED') THEN
    RAISE EXCEPTION 'COD chÆ°a á»Ÿ tráº¡ng thÃ¡i nháº­n Ä‘á»‘i soÃ¡t';
  END IF;

  a := assert_cash_account(p_account_id, 'VND', p_settled_at);
  SELECT coalesce(sum(amount_vnd), 0) INTO paid FROM cod_settlements WHERE cod_receivable_id = c.id;
  remaining := c.expected_cod_amount_vnd - paid;
  IF p_amount_vnd <= 0 OR p_amount_vnd > remaining THEN
    RAISE EXCEPTION 'Sá»‘ tiá»n COD vÆ°á»£t khoáº£n cÃ²n pháº£i thu';
  END IF;

  INSERT INTO cod_settlements(cod_receivable_id, amount_vnd, account_id, reference, settled_at, idempotency_key, created_by)
  VALUES(c.id, p_amount_vnd, a.id, left(coalesce(p_reference, ''), 300), p_settled_at, p_idempotency_key, p_actor)
  RETURNING * INTO s;

  INSERT INTO account_transactions(account_id, direction, amount, currency, reference_type, reference_id, transaction_type, occurred_at, description, idempotency_key, created_by)
  VALUES(a.id, 'IN', p_amount_vnd, 'VND', 'COD_SETTLEMENT', s.id::text, 'COD_SETTLEMENT', p_settled_at, 'COD order #' || c.order_id, p_idempotency_key || '-CASH', p_actor)
  RETURNING * INTO t;

  paid := paid + p_amount_vnd;
  UPDATE cod_receivables
  SET status = CASE WHEN paid = c.expected_cod_amount_vnd THEN 'SETTLED' ELSE 'PARTIALLY_SETTLED' END,
      settled_at = CASE WHEN paid = c.expected_cod_amount_vnd THEN p_settled_at END
  WHERE id = c.id;

  INSERT INTO activity_logs(entity_type, entity_id, action, changes, user_name)
  VALUES('COD_SETTLEMENT', s.id::text, 'CREATE', jsonb_build_object('event', CASE WHEN paid = c.expected_cod_amount_vnd THEN 'COD_SETTLED' ELSE 'COD_SETTLEMENT_RECORDED' END, 'cod_id', c.id, 'amount_vnd', p_amount_vnd, 'resolved_dispute', c.status = 'DISPUTED'), p_actor);
  RETURN to_jsonb(s);
END
$function$;
CREATE OR REPLACE FUNCTION public.get_financial_operations_summary()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
WITH receivables AS (
  SELECT r.*
  FROM public.customer_receivable_summaries r
),
refund_due AS (
  SELECT r.id, sum(coalesce(i.agreed_refund_rmb, i.expected_refund_rmb, 0)) expected
  FROM public.supplier_returns r
  JOIN public.supplier_return_items i
    ON i.supplier_return_id = r.id
   AND i.status NOT IN ('CANCELLED', 'REFUNDED', 'REPLACED', 'REJECTED')
  WHERE r.status IN ('WAITING_REFUND', 'PARTIALLY_RESOLVED')
  GROUP BY r.id
),
refund_paid AS (
  SELECT supplier_return_id, sum(amount_rmb) paid
  FROM public.supplier_refunds
  GROUP BY supplier_return_id
)
SELECT jsonb_build_object(
  'generated_at', timezone('utc', now()),
  'customer_receivable_vnd', (SELECT coalesce(sum(debt_amount), 0) * 1000000 FROM receivables),
  'customer_receivable_orders', (SELECT count(*) FROM receivables),
  'receivable_aging', coalesce((
    SELECT jsonb_object_agg(aging_bucket, jsonb_build_object('orders', n, 'amount_vnd', amount_vnd))
    FROM (
      SELECT aging_bucket, count(*) n, sum(debt_amount) * 1000000 amount_vnd
      FROM receivables
      GROUP BY aging_bucket
    ) x
  ), '{}'::jsonb),
  'cod', jsonb_build_object(
    'outstanding_vnd', (SELECT coalesce(sum(outstanding_vnd), 0) FROM public.cod_receivable_summaries WHERE status IN ('WAITING_SETTLEMENT', 'PARTIALLY_SETTLED', 'DISPUTED')),
    'in_transit_vnd', (SELECT coalesce(sum(expected_cod_amount_vnd), 0) FROM public.cod_receivable_summaries WHERE status = 'PENDING_DELIVERY'),
    'overdue_vnd', (SELECT coalesce(sum(outstanding_vnd), 0) FROM public.cod_receivable_summaries WHERE status IN ('WAITING_SETTLEMENT', 'PARTIALLY_SETTLED', 'DISPUTED') AND expected_settlement_at < now()),
    'disputed', (SELECT count(*) FROM public.cod_receivables WHERE status = 'DISPUTED')
  ),
  'supplier_payable_cny', (SELECT coalesce(sum(debt_rmb), 0) FROM public.purchase_batch_summaries WHERE status NOT IN ('DRAFT', 'CANCELLED', 'CLOSED')),
  'supplier_refund_pending_cny', (SELECT coalesce(sum(greatest(d.expected - coalesce(p.paid, 0), 0)), 0) FROM refund_due d LEFT JOIN refund_paid p ON p.supplier_return_id = d.id),
  'accounts', coalesce((SELECT jsonb_agg(to_jsonb(b) ORDER BY currency, code) FROM public.cash_account_balances b WHERE is_active), '[]'::jsonb),
  'reconciliation_differences', (SELECT count(*) FROM public.cash_account_balances WHERE is_active AND coalesce(last_difference, 0) <> 0)
);
$function$;
