CREATE OR REPLACE FUNCTION public.next_salesops_code(p_prefix text, p_table regclass, p_column text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE day text:=to_char(current_date,'YYYYMMDD');seq integer;result text;
BEGIN PERFORM pg_advisory_xact_lock(hashtext(p_prefix||day));EXECUTE format('SELECT coalesce(max((regexp_match(%I,$1))[1]::int),0)+1 FROM %s WHERE %I LIKE $2',p_column,p_table,p_column) INTO seq USING '(\d+)$',p_prefix||'-'||day||'-%';result:=p_prefix||'-'||day||'-'||lpad(seq::text,3,'0');RETURN result;END $function$;
CREATE OR REPLACE FUNCTION public.create_trade_in(p_data jsonb, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE t trade_ins%ROWTYPE;
BEGIN SELECT * INTO t FROM trade_ins WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(t);END IF;IF length(btrim(coalesce(p_data->>'brand',''))) NOT BETWEEN 1 AND 100 OR length(btrim(coalesce(p_data->>'model',''))) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'HÃ£ng vÃ  model lÃ  báº¯t buá»™c';END IF;INSERT INTO trade_ins(trade_in_code,customer_id,order_id,brand,model,serial,cpu,gpu,ram,ssd,status,reported_condition,notes,idempotency_key,created_by) VALUES(next_salesops_code('TI','trade_ins','trade_in_code'),nullif(p_data->>'customer_id','')::bigint,nullif(p_data->>'order_id','')::bigint,btrim(p_data->>'brand'),btrim(p_data->>'model'),nullif(btrim(coalesce(p_data->>'serial','')),''),nullif(p_data->>'cpu',''),nullif(p_data->>'gpu',''),nullif(p_data->>'ram',''),nullif(p_data->>'ssd',''),'DRAFT',left(coalesce(p_data->>'reported_condition',''),2000),left(coalesce(p_data->>'notes',''),2000),p_idempotency_key,p_actor) RETURNING * INTO t;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('TRADE_IN',t.id::text,'CREATE',jsonb_build_object('event','TRADE_IN_CREATED','code',t.trade_in_code),p_actor);RETURN to_jsonb(t);EXCEPTION WHEN unique_violation THEN SELECT * INTO t FROM trade_ins WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(t);END IF;RAISE;END $function$;
CREATE OR REPLACE FUNCTION public.start_trade_in_inspection(p_id uuid, p_user_id uuid, p_mainboard_status text, p_findings text, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE t trade_ins%ROWTYPE;i trade_in_inspections%ROWTYPE;
BEGIN SELECT * INTO i FROM trade_in_inspections WHERE trade_in_id=p_id AND status='IN_PROGRESS';IF FOUND THEN RETURN to_jsonb(i);END IF;SELECT * INTO t FROM trade_ins WHERE id=p_id FOR UPDATE;IF NOT FOUND OR t.status NOT IN('DRAFT','INSPECTING') THEN RAISE EXCEPTION 'Trade-in khÃ´ng thá»ƒ báº¯t Ä‘áº§u inspection';END IF;INSERT INTO trade_in_inspections(trade_in_id,mainboard_status,findings,inspected_by) VALUES(t.id,p_mainboard_status,left(coalesce(p_findings,''),5000),p_user_id) RETURNING * INTO i;UPDATE trade_ins SET status='INSPECTING',updated_at=timezone('utc',now()) WHERE id=t.id;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('TRADE_IN_INSPECTION',i.id::text,'CREATE',jsonb_build_object('event','TRADE_IN_INSPECTION_STARTED','trade_in_id',t.id,'idempotency_key',p_idempotency_key),p_actor);RETURN to_jsonb(i);END $function$;
CREATE OR REPLACE FUNCTION public.complete_trade_in_inspection(p_id uuid, p_mainboard_status text, p_findings text, p_checks jsonb, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE i trade_in_inspections%ROWTYPE;entry jsonb;
BEGIN
 SELECT * INTO i FROM trade_in_inspections WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'KhÃ´ng tÃ¬m tháº¥y inspection';END IF;
 IF i.status='COMPLETED' THEN RETURN to_jsonb(i);END IF;
 IF p_mainboard_status NOT IN('ORIGINAL','OFFICIAL_REPLACED','REPAIRED','UNKNOWN') OR jsonb_typeof(coalesce(p_checks,'[]'::jsonb))<>'array' OR jsonb_array_length(coalesce(p_checks,'[]'::jsonb))=0 THEN RAISE EXCEPTION 'Káº¿t quáº£ inspection khÃ´ng há»£p lá»‡';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(p_checks) LOOP
  IF entry->>'result' NOT IN('PASS','FAIL','WARNING','NOT_TESTED') OR btrim(coalesce(entry->>'check_key',''))='' THEN RAISE EXCEPTION 'Checklist khÃ´ng há»£p lá»‡';END IF;
  INSERT INTO trade_in_check_items(inspection_id,check_key,result,notes) VALUES(i.id,upper(left(entry->>'check_key',60)),entry->>'result',left(coalesce(entry->>'notes',''),1000));
 END LOOP;
 UPDATE trade_in_inspections SET status='COMPLETED',mainboard_status=p_mainboard_status,findings=left(coalesce(p_findings,''),5000),completed_at=timezone('utc',now()) WHERE id=i.id RETURNING * INTO i;
 UPDATE trade_ins SET status='QUOTED',updated_at=timezone('utc',now()) WHERE id=i.trade_in_id;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('TRADE_IN_INSPECTION',i.id::text,'UPDATE',jsonb_build_object('event','TRADE_IN_INSPECTION_COMPLETED','idempotency_key',p_idempotency_key),p_actor);
 RETURN to_jsonb(i);
END $function$;
