BEGIN IF p_agreed<=0 THEN RAISE EXCEPTION 'GiÃ¡ trá»‹ thá»a thuáº­n pháº£i lá»›n hÆ¡n 0';END IF;SELECT * INTO t FROM trade_ins WHERE id=p_id FOR UPDATE;IF NOT FOUND OR t.status NOT IN('QUOTED','INSPECTING') THEN RAISE EXCEPTION 'Trade-in chÆ°a sáºµn sÃ ng cháº¥p nháº­n';END IF;SELECT * INTO o FROM orders WHERE id=p_order_id FOR UPDATE;IF NOT FOUND OR o.order_status IN('cancelled','returned') THEN RAISE EXCEPTION 'Order khÃ´ng há»£p lá»‡';END IF;IF o.debt_amount*1000000<p_agreed THEN RAISE EXCEPTION 'Trade-in credit vÆ°á»£t nghÄ©a vá»¥ khÃ¡ch hÃ ng';END IF;UPDATE orders SET trade_in_credit_vnd=trade_in_credit_vnd+p_agreed,debt_amount=debt_amount-p_agreed/1000000,trade_in_laptop_id=NULL,updated_at=timezone('utc',now()) WHERE id=o.id;UPDATE trade_ins SET status='ACCEPTED',order_id=o.id,estimated_value_vnd=p_estimated,agreed_value_vnd=p_agreed,updated_at=timezone('utc',now()) WHERE id=t.id RETURNING * INTO t;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('TRADE_IN',t.id::text,'UPDATE',jsonb_build_object('event','TRADE_IN_ACCEPTED','order_id',o.id,'credit_vnd',p_agreed),p_actor);RETURN to_jsonb(t);END $function$;
