 VALUES(l.id,'TRADE_IN_ACQUISITION',t.agreed_value_vnd,'TRADE_IN',t.id::text,'Thu cÅ© Ä‘á»•i má»›i '||t.trade_in_code,p_actor);
 UPDATE trade_ins SET status='CONVERTED_TO_INVENTORY',inventory_laptop_id=l.id,updated_at=timezone('utc',now()) WHERE id=t.id;
 RETURN to_jsonb(l);
