AS $function$ DECLARE c commissions%ROWTYPE;a cash_accounts%ROWTYPE;tx account_transactions%ROWTYPE;BEGIN SELECT * INTO c FROM commissions WHERE id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'KhÃ´ng tÃ¬m tháº¥y commission';END IF;IF c.status='PAID' THEN RETURN to_jsonb(c);END IF;IF c.status<>'APPROVED' THEN RAISE EXCEPTION 'Commission chÆ°a Ä‘Æ°á»£c duyá»‡t';END IF;a:=assert_cash_account(p_account_id,'VND',timezone('utc',now()));INSERT INTO account_transactions(account_id,direction,amount,currency,reference_type,reference_id,transaction_type,occurred_at,description,idempotency_key,created_by) VALUES(a.id,'OUT',c.amount_vnd,'VND','COMMISSION',c.id::text,'COMMISSION_PAYMENT',timezone('utc',now()),'Chi hoa há»“ng order #'||c.order_id,p_idempotency_key||'-CASH',p_actor) RETURNING * INTO tx;UPDATE commissions SET status='PAID',paid_at=timezone('utc',now()),payment_account_id=a.id,payment_reference=left(coalesce(p_reference,''),300),updated_at=timezone('utc',now()) WHERE id=c.id RETURNING * INTO c;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('COMMISSION',c.id::text,'UPDATE',jsonb_build_object('event','COMMISSION_PAID','account_id',a.id),p_actor);RETURN to_jsonb(c);END $function$;
CREATE OR REPLACE FUNCTION public.guard_commission_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' AND OLD.status IN('APPROVED','PAID') THEN RAISE EXCEPTION 'Commission Ä‘Ã£ duyá»‡t/chi khÃ´ng thá»ƒ xÃ³a';END IF;
 IF TG_OP='UPDATE' AND OLD.status IN('APPROVED','PAID') AND (NEW.amount_vnd IS DISTINCT FROM OLD.amount_vnd OR NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.beneficiary_type IS DISTINCT FROM OLD.beneficiary_type OR NEW.beneficiary_user_id IS DISTINCT FROM OLD.beneficiary_user_id OR NEW.beneficiary_name IS DISTINCT FROM OLD.beneficiary_name OR NEW.commission_type IS DISTINCT FROM OLD.commission_type OR NEW.calculation_basis IS DISTINCT FROM OLD.calculation_basis OR NEW.calculation_snapshot_json IS DISTINCT FROM OLD.calculation_snapshot_json) THEN RAISE EXCEPTION 'Commission Ä‘Ã£ duyá»‡t lÃ  báº¥t biáº¿n';END IF;
 IF TG_OP='UPDATE' AND OLD.status='PAID' AND NEW.status<>'PAID' THEN RAISE EXCEPTION 'Commission Ä‘Ã£ chi khÃ´ng thá»ƒ Ä‘á»•i tráº¡ng thÃ¡i';END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$;
