  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.sync_laptop_purchase_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF coalesce(NEW.purchase_price_rmb,0)=0 AND coalesce(NEW.price_rmb,0)>0 THEN NEW.purchase_price_rmb:=NEW.price_rmb; END IF;
  IF coalesce(NEW.price_rmb,0)=0 AND coalesce(NEW.purchase_price_rmb,0)>0 THEN NEW.price_rmb:=NEW.purchase_price_rmb; END IF;
  NEW.purchase_exchange_rate:=coalesce(NEW.purchase_exchange_rate,NEW.exchange_rate);
  NEW.exchange_rate:=coalesce(NEW.exchange_rate,NEW.purchase_exchange_rate);
  NEW.tracking_code_cn:=coalesce(nullif(NEW.tracking_code_cn,''),NEW.tracking_code,'');
  NEW.tracking_code:=coalesce(NEW.tracking_code,nullif(NEW.tracking_code_cn,''));
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.create_purchase_batch(p_batch jsonb, p_laptops jsonb, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE b purchase_batches%ROWTYPE; entry jsonb; created_rows jsonb; rate numeric;
BEGIN
  SELECT result INTO created_rows FROM operation_requests
  WHERE idempotency_key=p_idempotency_key AND operation='CREATE_PURCHASE_BATCH';
  IF FOUND THEN RETURN created_rows; END IF;
  IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100
     OR jsonb_typeof(p_laptops) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_laptops) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'LÃ´ mua pháº£i cÃ³ tá»« 1 Ä‘áº¿n 200 mÃ¡y';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM suppliers WHERE id=(p_batch->>'supplier_id')::uuid AND active) THEN
    RAISE EXCEPTION 'NhÃ  cung cáº¥p khÃ´ng tá»“n táº¡i hoáº·c Ä‘Ã£ ngá»«ng sá»­ dá»¥ng';
  END IF;
  rate:=coalesce(nullif(p_batch->>'purchase_exchange_rate','')::numeric,nullif(p_batch->>'exchange_rate','')::numeric);
  IF rate IS NULL OR rate<=0 THEN RAISE EXCEPTION 'Tá»· giÃ¡ mua khÃ´ng há»£p lá»‡'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_laptops) x WHERE
    length(btrim(coalesce(x->>'name',''))) NOT BETWEEN 1 AND 240
    OR NOT EXISTS(SELECT 1 FROM app_options o WHERE o.group_key='category' AND o.option_key=x->>'category' AND o.is_active IS TRUE)
    OR coalesce(nullif(x->>'purchase_price_rmb','')::numeric,-1)<0
    OR coalesce(nullif(x->>'shipping_rmb','')::numeric,0)<0
    OR length(coalesce(x->>'tracking_code_cn',''))>200) THEN
    RAISE EXCEPTION 'ThÃ´ng tin mÃ¡y trong lÃ´ khÃ´ng há»£p lá»‡';
  END IF;

  INSERT INTO purchase_batches(batch_code,supplier_id,purchase_date,currency,exchange_rate,
    subtotal_rmb,domestic_shipping_rmb,other_cost_rmb,destination,status,notes,active,
    created_by,updated_by,idempotency_key,procurement_flow)
  VALUES(next_purchase_batch_code((p_batch->>'purchase_date')::date),(p_batch->>'supplier_id')::uuid,
    (p_batch->>'purchase_date')::date,'CNY',rate,0,0,0,'OTHER','CONFIRMED',
    left(coalesce(p_batch->>'notes',''),3000),true,p_actor,p_actor,p_idempotency_key,'DIRECT')
  RETURNING * INTO b;

  FOR entry IN SELECT value FROM jsonb_array_elements(p_laptops) LOOP
    INSERT INTO laptops(name,category,serial,tracking_code_cn,purchase_price_rmb,shipping_rmb,
      purchase_exchange_rate,purchase_batch_id,source_type,status,location,charger_status,
      is_active,condition_note,created_by,import_date,month_key,price_rmb,exchange_rate,tracking_code)
    VALUES(btrim(entry->>'name'),entry->>'category',nullif(left(btrim(coalesce(entry->>'serial','')),100),''),
      left(btrim(coalesce(entry->>'tracking_code_cn','')),200),
      (entry->>'purchase_price_rmb')::numeric,coalesce(nullif(entry->>'shipping_rmb','')::numeric,0),
      rate,b.id,'SUPPLIER_PURCHASE','in_transit','wh_cn','unchecked',true,
      left(coalesce(entry->>'notes',''),2000),p_actor,b.purchase_date,to_char(b.purchase_date,'MM/YYYY'),
      (entry->>'purchase_price_rmb')::numeric,rate,left(btrim(coalesce(entry->>'tracking_code_cn','')),200));
  END LOOP;
  SELECT jsonb_build_object('batch',to_jsonb(b),'laptops',coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb))
  INTO created_rows FROM laptops l WHERE l.purchase_batch_id=b.id;
  INSERT INTO operation_requests(idempotency_key,operation,result,created_by)
  VALUES(p_idempotency_key,'CREATE_PURCHASE_BATCH',created_rows,p_actor);
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('PURCHASE_BATCH',b.id::text,'CREATE',jsonb_build_object('batch_code',b.batch_code,'laptop_count',jsonb_array_length(p_laptops)),p_actor);
  RETURN created_rows;
END $function$;
CREATE OR REPLACE FUNCTION public.receive_purchase_laptops(p_items jsonb, p_notes text, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE entry jsonb; l laptops%ROWTYPE; rows jsonb:='[]'::jsonb; prior jsonb;
BEGIN
  SELECT result INTO prior FROM operation_requests
  WHERE idempotency_key=p_idempotency_key AND operation='RECEIVE_PURCHASE_LAPTOPS';
  IF FOUND THEN RETURN prior; END IF;
  IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100
     OR jsonb_typeof(p_items) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'Äá»£t nháº­n hÃ ng khÃ´ng há»£p lá»‡';
  END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(p_items)) <>
     (SELECT count(DISTINCT (value->>'laptop_id')::bigint) FROM jsonb_array_elements(p_items)) THEN
    RAISE EXCEPTION 'Danh sÃ¡ch nháº­n hÃ ng cÃ³ mÃ¡y bá»‹ trÃ¹ng';
  END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    SELECT * INTO l FROM laptops WHERE id=(entry->>'laptop_id')::bigint FOR UPDATE;
    IF NOT FOUND OR l.source_type NOT IN('SUPPLIER_PURCHASE','SUPPLIER_REPLACEMENT') THEN
      RAISE EXCEPTION 'MÃ¡y khÃ´ng thuá»™c luá»“ng mua tá»« nhÃ  cung cáº¥p';
    END IF;
    IF l.status<>'in_transit' THEN RAISE EXCEPTION 'MÃ¡y % khÃ´ng cÃ²n á»Ÿ tráº¡ng thÃ¡i chÆ°a vá» hÃ ng',l.id; END IF;
    PERFORM set_config('app.laptop_transition','on',true);
    UPDATE laptops SET
      status='waiting_qc',received_at=coalesce(nullif(entry->>'received_at','')::date,current_date)::timestamptz,
      warehouse_date=coalesce(nullif(entry->>'received_at','')::date,current_date),location='store',
      serial=coalesce(nullif(left(btrim(coalesce(entry->>'serial','')),100),''),serial),
      tracking_code_cn=coalesce(nullif(left(btrim(coalesce(entry->>'tracking_code_cn','')),200),''),tracking_code_cn),
      tracking_code=coalesce(nullif(left(btrim(coalesce(entry->>'tracking_code_cn','')),200),''),tracking_code),
      charger_status=coalesce(nullif(entry->>'charger_status',''),charger_status),
      condition_note=left(concat_ws(E'\n',nullif(condition_note,''),nullif(entry->>'notes',''),nullif(p_notes,'')),2000)
    WHERE id=l.id RETURNING * INTO l;
    INSERT INTO stock_movements(laptop_id,movement_type,from_location,to_location,note,performed_by,reference_type,reference_id)
    VALUES(l.id,'PURCHASE_RECEIVE','IN_TRANSIT',l.location,'Nháº­n hÃ ng tá»« lÃ´ '||coalesce(l.purchase_batch_id::text,''),p_actor,'PURCHASE_BATCH',l.purchase_batch_id::text);
    rows:=rows||jsonb_build_array(to_jsonb(l));
  END LOOP;
  prior:=jsonb_build_object('laptops',rows,'received_count',jsonb_array_length(rows));
  INSERT INTO operation_requests(idempotency_key,operation,result,created_by)
  VALUES(p_idempotency_key,'RECEIVE_PURCHASE_LAPTOPS',prior,p_actor);
  RETURN prior;
END $function$;
CREATE OR REPLACE FUNCTION public.receive_unknown_laptop(p_data jsonb, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE; prior jsonb;
BEGIN
  SELECT result INTO prior FROM operation_requests
  WHERE idempotency_key=p_idempotency_key AND operation='RECEIVE_UNKNOWN_LAPTOP';
  IF FOUND THEN RETURN prior; END IF;
  IF length(btrim(coalesce(p_data->>'name',''))) NOT BETWEEN 1 AND 240 THEN RAISE EXCEPTION 'TÃªn mÃ¡y khÃ´ng há»£p lá»‡'; END IF;
  INSERT INTO laptops(name,serial,tracking_code_cn,tracking_code,source_type,status,
    location,charger_status,is_active,condition_note,received_at,warehouse_date,created_by)
  VALUES(btrim(p_data->>'name'),nullif(left(btrim(coalesce(p_data->>'serial','')),100),''),left(btrim(coalesce(p_data->>'tracking_code_cn','')),200),
    left(btrim(coalesce(p_data->>'tracking_code_cn','')),200),'UNKNOWN','waiting_qc','store',
    coalesce(nullif(p_data->>'charger_status',''),'unchecked'),true,left(coalesce(p_data->>'notes',''),2000),
    coalesce(nullif(p_data->>'received_at','')::date,current_date)::timestamptz,
    coalesce(nullif(p_data->>'received_at','')::date,current_date),p_actor) RETURNING * INTO l;
  prior:=to_jsonb(l);
  INSERT INTO operation_requests(idempotency_key,operation,result,created_by)
  VALUES(p_idempotency_key,'RECEIVE_UNKNOWN_LAPTOP',prior,p_actor);
  INSERT INTO stock_movements(laptop_id,movement_type,to_location,note,performed_by,reference_type,reference_id)
  VALUES(l.id,'PURCHASE_RECEIVE',l.location,'Nháº­n mÃ¡y chÆ°a rÃµ nguá»“n',p_actor,'UNKNOWN_INTAKE',p_idempotency_key);
  RETURN prior;
END $function$;
CREATE OR REPLACE FUNCTION public.receive_inventory(p_expected jsonb, p_unknown jsonb, p_notes text, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE prior jsonb; known_result jsonb:=jsonb_build_object('laptops','[]'::jsonb,'received_count',0);
  entry jsonb; unknown_rows jsonb:='[]'::jsonb; unknown_row jsonb; index_no integer:=0;
BEGIN
  SELECT result INTO prior FROM operation_requests
  WHERE idempotency_key=p_idempotency_key AND operation='RECEIVE_INVENTORY';
  IF FOUND THEN RETURN prior; END IF;
  IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 80
     OR jsonb_typeof(coalesce(p_expected,'[]'::jsonb)) IS DISTINCT FROM 'array'
     OR jsonb_typeof(coalesce(p_unknown,'[]'::jsonb)) IS DISTINCT FROM 'array'
     OR jsonb_array_length(coalesce(p_expected,'[]'::jsonb))+jsonb_array_length(coalesce(p_unknown,'[]'::jsonb)) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'Äá»£t nháº­n hÃ ng khÃ´ng há»£p lá»‡';
  END IF;
  IF jsonb_array_length(coalesce(p_expected,'[]'::jsonb))>0 THEN
    known_result:=receive_purchase_laptops(p_expected,p_notes,p_actor,p_idempotency_key||'-expected');
  END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(coalesce(p_unknown,'[]'::jsonb)) LOOP
    index_no:=index_no+1;
    unknown_row:=receive_unknown_laptop(entry,p_actor,p_idempotency_key||'-unknown-'||index_no::text);
    unknown_rows:=unknown_rows||jsonb_build_array(unknown_row);
  END LOOP;
  prior:=jsonb_build_object('expected',known_result->'laptops','unknown',unknown_rows,
    'received_count',jsonb_array_length(coalesce(known_result->'laptops','[]'::jsonb))+jsonb_array_length(unknown_rows));
  INSERT INTO operation_requests(idempotency_key,operation,result,created_by)
  VALUES(p_idempotency_key,'RECEIVE_INVENTORY',prior,p_actor);
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('RECEIVING',p_idempotency_key,'CREATE',jsonb_build_object('received_count',prior->'received_count','notes',left(coalesce(p_notes,''),1000)),p_actor);
  RETURN prior;
END $function$;
CREATE OR REPLACE FUNCTION public.reconcile_unknown_laptop(p_unknown_laptop_id bigint, p_expected_laptop_id bigint, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE physical laptops%ROWTYPE; expected laptops%ROWTYPE; prior jsonb;
BEGIN
  SELECT result INTO prior FROM operation_requests
  WHERE idempotency_key=p_idempotency_key AND operation='RECONCILE_UNKNOWN_LAPTOP';
  IF FOUND THEN RETURN prior; END IF;
  IF p_unknown_laptop_id=p_expected_laptop_id THEN RAISE EXCEPTION 'Hai laptop pháº£i khÃ¡c nhau'; END IF;
  PERFORM pg_advisory_xact_lock(least(p_unknown_laptop_id,p_expected_laptop_id));
  PERFORM pg_advisory_xact_lock(greatest(p_unknown_laptop_id,p_expected_laptop_id));
  SELECT * INTO physical FROM laptops WHERE id=p_unknown_laptop_id FOR UPDATE;
  SELECT * INTO expected FROM laptops WHERE id=p_expected_laptop_id FOR UPDATE;
  IF physical.id IS NULL OR physical.source_type<>'UNKNOWN' OR physical.status<>'waiting_qc' THEN
    RAISE EXCEPTION 'Laptop thá»±c nháº­n khÃ´ng cÃ²n lÃ  mÃ¡y chÆ°a rÃµ nguá»“n Ä‘ang chá» QC';
  END IF;
  IF expected.id IS NULL OR expected.status<>'in_transit' OR expected.source_type NOT IN('SUPPLIER_PURCHASE','SUPPLIER_REPLACEMENT') THEN
    RAISE EXCEPTION 'Laptop dá»± kiáº¿n khÃ´ng cÃ²n nguyÃªn tráº¡ng chÆ°a vá» hÃ ng';
  END IF;
  IF EXISTS(SELECT 1 FROM qc_inspections WHERE laptop_id=expected.id)
     OR EXISTS(SELECT 1 FROM repair_jobs WHERE laptop_id=expected.id)
     OR EXISTS(SELECT 1 FROM orders WHERE laptop_id=expected.id OR requested_laptop_id=expected.id)
     OR EXISTS(SELECT 1 FROM reservations WHERE laptop_id=expected.id)
     OR EXISTS(SELECT 1 FROM stock_movements WHERE laptop_id=expected.id) THEN
    RAISE EXCEPTION 'Laptop dá»± kiáº¿n Ä‘Ã£ cÃ³ lá»‹ch sá»­ nghiá»‡p vá»¥, khÃ´ng thá»ƒ gá»™p';
  END IF;
  -- Release unique serial/tracking keys held by the untouched placeholder before
  -- copying its source data onto the physical laptop that keeps the stable ID.
  DELETE FROM laptops WHERE id=expected.id;
  UPDATE laptops SET purchase_batch_id=expected.purchase_batch_id,source_type=expected.source_type,
    purchase_price_rmb=expected.purchase_price_rmb,shipping_rmb=expected.shipping_rmb,
    purchase_exchange_rate=expected.purchase_exchange_rate,price_rmb=expected.purchase_price_rmb,
    exchange_rate=expected.purchase_exchange_rate,tracking_code_cn=coalesce(nullif(expected.tracking_code_cn,''),tracking_code_cn),
    tracking_code=coalesce(nullif(expected.tracking_code_cn,''),tracking_code),
    name=coalesce(nullif(name,''),expected.name),
    serial=coalesce(serial,expected.serial),import_date=expected.import_date,month_key=expected.month_key,
    source_reference_id=expected.source_reference_id
  WHERE id=physical.id RETURNING * INTO physical;
  prior:=to_jsonb(physical);
  INSERT INTO operation_requests(idempotency_key,operation,result,created_by)
  VALUES(p_idempotency_key,'RECONCILE_UNKNOWN_LAPTOP',prior,p_actor);
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('LAPTOP',physical.id::text,'UPDATE',jsonb_build_object('event','UNKNOWN_SOURCE_RECONCILED','deleted_expected_laptop_id',expected.id,'purchase_batch_id',physical.purchase_batch_id),p_actor);
  RETURN prior;
END $function$;
CREATE OR REPLACE FUNCTION public.update_incoming_tracking(p_laptop_id bigint, p_tracking text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE; old_tracking text; normalized text:=left(btrim(coalesce(p_tracking,'')),200);
BEGIN
  SELECT tracking_code_cn INTO old_tracking FROM laptops WHERE id=p_laptop_id AND is_active IS TRUE FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Laptop không tồn tại hoặc đã ngừng sử dụng'; END IF;
  IF EXISTS(SELECT 1 FROM laptops WHERE id<>p_laptop_id AND is_active IS TRUE
    AND btrim(normalized)<>'' AND lower(btrim(tracking_code_cn))=lower(btrim(normalized))) THEN
    RAISE EXCEPTION 'Mã vận chuyển đã được dùng cho laptop khác';
  END IF;
  UPDATE laptops SET tracking_code_cn=normalized,tracking_code=nullif(normalized,'') WHERE id=p_laptop_id RETURNING * INTO l;
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('LAPTOP',l.id::text,'UPDATE',jsonb_build_object('event','TRACKING_CORRECTED','old',old_tracking,'new',l.tracking_code_cn),p_actor);
  RETURN to_jsonb(l);
END $function$;
CREATE OR REPLACE FUNCTION public.update_laptop_procurement(p_laptop_id bigint, p_data jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE; target_batch purchase_batches%ROWTYPE; next_tracking text;
BEGIN
  SELECT * INTO l FROM laptops WHERE id=p_laptop_id AND is_active IS TRUE FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Laptop không tồn tại hoặc đã ngừng sử dụng'; END IF;
  IF l.status='sold' THEN RAISE EXCEPTION 'Laptop đã bán: snapshot giá vốn và dữ liệu mua hàng là bất biến'; END IF;
  IF l.status='supplier_return' AND EXISTS(SELECT 1 FROM supplier_refunds sr JOIN supplier_return_items sri ON sri.supplier_return_id=sr.supplier_return_id WHERE sri.laptop_id=l.id) THEN
    RAISE EXCEPTION 'Laptop đang trả NCC và đã phát sinh tài chính; không thể sửa dữ liệu mua hàng';
  END IF;
  IF l.status NOT IN('in_transit','waiting_qc','repair','available','reserved','supplier_return') THEN RAISE EXCEPTION 'Trạng thái laptop không cho phép sửa dữ liệu mua hàng'; END IF;
  IF p_data ? 'name' AND length(btrim(coalesce(p_data->>'name',''))) NOT BETWEEN 1 AND 240 THEN RAISE EXCEPTION 'Tên máy không hợp lệ'; END IF;
  IF p_data ? 'category' AND NOT EXISTS(
    SELECT 1 FROM app_options o
    WHERE o.group_key='category' AND o.option_key=p_data->>'category' AND o.is_active IS TRUE
  ) THEN RAISE EXCEPTION 'Phân loại máy không hợp lệ'; END IF;
  IF p_data ? 'purchase_price_rmb' AND (p_data->>'purchase_price_rmb')::numeric < 0 THEN RAISE EXCEPTION 'Giá mua không hợp lệ'; END IF;
  IF p_data ? 'shipping_rmb' AND coalesce(nullif(p_data->>'shipping_rmb','')::numeric,0) < 0 THEN RAISE EXCEPTION 'Phí vận chuyển không hợp lệ'; END IF;
  next_tracking:=CASE WHEN p_data ? 'tracking_code_cn' THEN left(btrim(coalesce(p_data->>'tracking_code_cn','')),200) ELSE l.tracking_code_cn END;
  IF EXISTS(SELECT 1 FROM laptops x WHERE x.id<>l.id AND x.is_active IS TRUE AND btrim(next_tracking)<>'' AND lower(btrim(x.tracking_code_cn))=lower(btrim(next_tracking))) THEN RAISE EXCEPTION 'Mã vận chuyển đã được dùng cho laptop khác'; END IF;
  IF p_data ? 'purchase_batch_id' THEN
    SELECT * INTO target_batch FROM purchase_batches WHERE id=(p_data->>'purchase_batch_id')::bigint AND active IS TRUE FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Lô mua đích không tồn tại hoặc đã ngừng sử dụng'; END IF;
    IF EXISTS(SELECT 1 FROM supplier_payments WHERE purchase_batch_id=l.purchase_batch_id) AND target_batch.id IS DISTINCT FROM l.purchase_batch_id THEN RAISE EXCEPTION 'Không thể chuyển lô sau khi lô nguồn đã phát sinh thanh toán NCC'; END IF;
  END IF;
  UPDATE laptops SET
    name=CASE WHEN p_data ? 'name' THEN left(btrim(p_data->>'name'),240) ELSE name END,
    category=CASE WHEN p_data ? 'category' THEN p_data->>'category' ELSE category END,
    serial=CASE WHEN p_data ? 'serial' THEN nullif(left(btrim(coalesce(p_data->>'serial','')),100),'') ELSE serial END,
    tracking_code_cn=next_tracking,tracking_code=nullif(next_tracking,''),
    purchase_price_rmb=CASE WHEN p_data ? 'purchase_price_rmb' THEN (p_data->>'purchase_price_rmb')::numeric ELSE purchase_price_rmb END,
    price_rmb=CASE WHEN p_data ? 'purchase_price_rmb' THEN (p_data->>'purchase_price_rmb')::numeric ELSE price_rmb END,
    shipping_rmb=CASE WHEN p_data ? 'shipping_rmb' THEN coalesce(nullif(p_data->>'shipping_rmb','')::numeric,0) ELSE shipping_rmb END,
    condition_note=CASE WHEN p_data ? 'notes' THEN left(coalesce(p_data->>'notes',''),2000) ELSE condition_note END,
    purchase_batch_id=CASE WHEN p_data ? 'purchase_batch_id' THEN target_batch.id ELSE purchase_batch_id END,
    purchase_exchange_rate=CASE WHEN p_data ? 'purchase_batch_id' THEN target_batch.exchange_rate ELSE purchase_exchange_rate END,
    exchange_rate=CASE WHEN p_data ? 'purchase_batch_id' THEN target_batch.exchange_rate ELSE exchange_rate END,
    import_date=CASE WHEN p_data ? 'purchase_batch_id' THEN target_batch.purchase_date ELSE import_date END,
    month_key=CASE WHEN p_data ? 'purchase_batch_id' THEN to_char(target_batch.purchase_date,'MM/YYYY') ELSE month_key END
  WHERE id=l.id RETURNING * INTO l;
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('LAPTOP',l.id::text,'UPDATE',jsonb_build_object('event','PROCUREMENT_CORRECTED','fields',p_data),p_actor);
  RETURN to_jsonb(l);
END $function$;CREATE OR REPLACE FUNCTION public.ignore_incoming_laptop(p_laptop_id bigint, p_reason text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE;
BEGIN
  IF btrim(coalesce(p_reason,''))='' THEN RAISE EXCEPTION 'Cáº§n nháº­p lÃ½ do bá» qua'; END IF;
  PERFORM set_config('app.laptop_transition','on',true);
  UPDATE laptops SET status='ignored',ignored_at=timezone('utc',now()),ignored_by=p_actor,
    ignore_reason=left(btrim(p_reason),1000),is_active=false
  WHERE id=p_laptop_id AND status='in_transit' RETURNING * INTO l;
  IF NOT FOUND THEN RAISE EXCEPTION 'MÃ¡y khÃ´ng cÃ²n á»Ÿ tráº¡ng thÃ¡i cÃ³ thá»ƒ bá» qua'; END IF;
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('LAPTOP',l.id::text,'UPDATE',jsonb_build_object('event','INCOMING_LAPTOP_IGNORED','reason',l.ignore_reason),p_actor);
  RETURN to_jsonb(l);
END $function$;
CREATE OR REPLACE FUNCTION public.link_supplier_replacement(p_item_id bigint, p_replacement_laptop_id bigint, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE item supplier_return_items%ROWTYPE; r supplier_returns%ROWTYPE; replacement laptops%ROWTYPE; replacement_supplier uuid;
BEGIN
 SELECT * INTO item FROM supplier_return_items WHERE id=p_item_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'KhÃ´ng tÃ¬m tháº¥y sáº£n pháº©m tráº£'; END IF;
 SELECT * INTO r FROM supplier_returns WHERE id=item.supplier_return_id FOR UPDATE; IF r.status<>'WAITING_REPLACEMENT' THEN RAISE EXCEPTION 'Phiáº¿u tráº£ chÆ°a chá» replacement'; END IF;
 SELECT * INTO replacement FROM laptops WHERE id=p_replacement_laptop_id FOR UPDATE;
 IF NOT FOUND OR replacement.source_type<>'SUPPLIER_REPLACEMENT' OR replacement.status NOT IN('in_transit','waiting_qc') THEN RAISE EXCEPTION 'Laptop replacement khÃ´ng há»£p lá»‡'; END IF;
 SELECT supplier_id INTO replacement_supplier FROM purchase_batches WHERE id=replacement.purchase_batch_id;
 IF replacement_supplier IS DISTINCT FROM r.supplier_id THEN RAISE EXCEPTION 'Replacement khÃ´ng cÃ¹ng nhÃ  cung cáº¥p'; END IF;
 UPDATE supplier_return_items SET replacement_laptop_id=replacement.id,status='REPLACED' WHERE id=item.id RETURNING * INTO item;
 IF NOT EXISTS(SELECT 1 FROM supplier_return_items WHERE supplier_return_id=r.id AND status NOT IN('REPLACED','CANCELLED')) THEN UPDATE supplier_returns SET status='REPLACED' WHERE id=r.id; END IF;
 INSERT INTO supplier_return_events(supplier_return_id,event_type,details,performed_by) VALUES(r.id,'REPLACEMENT_LINKED',jsonb_build_object('item_id',item.id,'replacement_laptop_id',replacement.id),p_actor);
 RETURN to_jsonb(item);
END $function$;

-- TRIGGERS
CREATE TRIGGER account_transactions_append_only BEFORE DELETE OR UPDATE ON account_transactions FOR EACH ROW EXECUTE FUNCTION guard_account_transaction_history();
CREATE TRIGGER activity_logs_append_only_trigger BEFORE DELETE OR UPDATE ON activity_logs FOR EACH ROW EXECUTE FUNCTION prevent_activity_log_mutation();
CREATE TRIGGER app_options_set_updated_at_trigger BEFORE UPDATE ON app_options FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER app_settings_set_updated_at_trigger BEFORE UPDATE ON app_settings FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER cash_accounts_updated BEFORE UPDATE ON cash_accounts FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER cod_receivables_updated BEFORE UPDATE ON cod_receivables FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER cod_settlements_append_only BEFORE DELETE OR UPDATE ON cod_settlements FOR EACH ROW EXECUTE FUNCTION guard_account_transaction_history();
CREATE TRIGGER commissions_immutable BEFORE DELETE OR UPDATE ON commissions FOR EACH ROW EXECUTE FUNCTION guard_commission_history();
CREATE TRIGGER customers_set_updated_at_trigger BEFORE UPDATE ON customers FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER invoices_sync_from_financial_records AFTER INSERT OR DELETE OR UPDATE ON financial_records FOR EACH ROW EXECUTE FUNCTION sync_invoice_payment_trigger();
CREATE TRIGGER laptop_cost_components_immutable BEFORE DELETE OR UPDATE ON laptop_cost_components FOR EACH ROW EXECUTE FUNCTION guard_laptop_cost_component_history();
CREATE TRIGGER laptops_set_updated_at_trigger BEFORE UPDATE ON laptops FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER laptops_status_workflow_guard BEFORE UPDATE OF status ON laptops FOR EACH ROW EXECUTE FUNCTION guard_laptop_status_transition();
CREATE TRIGGER laptops_sync_purchase_fields_trigger BEFORE INSERT OR UPDATE OF purchase_price_rmb, price_rmb, purchase_exchange_rate, exchange_rate, tracking_code_cn, tracking_code ON laptops FOR EACH ROW EXECUTE FUNCTION sync_laptop_purchase_fields();
CREATE TRIGGER guard_order_sellable_laptop_trigger BEFORE INSERT OR UPDATE OF laptop_id, requested_laptop_id ON orders FOR EACH ROW EXECUTE FUNCTION guard_order_sellable_laptop();
CREATE TRIGGER invoices_sync_from_order_payment AFTER UPDATE OF payment_status, amount_paid, debt_amount ON orders FOR EACH ROW EXECUTE FUNCTION sync_invoice_order_payment_trigger();
