-- MIGRATION: 20260927_qc_product_consistency.sql
-- Incremental upgrade for databases already using the clean baseline.
-- Preserve detailed QC enums on the inspection and project compatible values
-- into the product fields used by Inventory and Settings.

CREATE OR REPLACE FUNCTION public.sync_laptop_purchase_fields()
RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public', 'pg_temp'
AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.purchase_price_rmb IS DISTINCT FROM OLD.purchase_price_rmb THEN
      IF NEW.price_rmb IS DISTINCT FROM OLD.price_rmb AND NEW.price_rmb IS DISTINCT FROM NEW.purchase_price_rmb THEN
        RAISE EXCEPTION 'Giá mua và giá nhập không thống nhất';
      END IF;
      NEW.price_rmb := NEW.purchase_price_rmb;
    ELSIF NEW.price_rmb IS DISTINCT FROM OLD.price_rmb THEN
      NEW.purchase_price_rmb := coalesce(NEW.price_rmb,0);
    END IF;
    IF NEW.purchase_exchange_rate IS DISTINCT FROM OLD.purchase_exchange_rate THEN
      IF NEW.exchange_rate IS DISTINCT FROM OLD.exchange_rate AND NEW.exchange_rate IS DISTINCT FROM NEW.purchase_exchange_rate THEN
        RAISE EXCEPTION 'Tỷ giá mua và tỷ giá nhập không thống nhất';
      END IF;
      NEW.exchange_rate := NEW.purchase_exchange_rate;
    ELSIF NEW.exchange_rate IS DISTINCT FROM OLD.exchange_rate THEN
      NEW.purchase_exchange_rate := NEW.exchange_rate;
    END IF;
    IF NEW.tracking_code_cn IS DISTINCT FROM OLD.tracking_code_cn THEN
      NEW.tracking_code := nullif(NEW.tracking_code_cn,'');
    ELSIF NEW.tracking_code IS DISTINCT FROM OLD.tracking_code THEN
      NEW.tracking_code_cn := coalesce(NEW.tracking_code,'');
    END IF;
  ELSE
    IF coalesce(NEW.purchase_price_rmb,0)=0 AND coalesce(NEW.price_rmb,0)>0 THEN
      NEW.purchase_price_rmb := NEW.price_rmb;
    END IF;
    NEW.price_rmb := NEW.purchase_price_rmb;
    NEW.purchase_exchange_rate := coalesce(NEW.purchase_exchange_rate,NEW.exchange_rate);
    NEW.exchange_rate := NEW.purchase_exchange_rate;
    NEW.tracking_code_cn := coalesce(nullif(NEW.tracking_code_cn,''),NEW.tracking_code,'');
    NEW.tracking_code := nullif(NEW.tracking_code_cn,'');
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.sync_completed_qc_product()
RETURNS trigger LANGUAGE plpgsql
SET search_path TO 'public', 'pg_temp'
AS $$
BEGIN
  IF NEW.status <> 'COMPLETED' OR OLD.status = 'COMPLETED' THEN RETURN NEW; END IF;
  IF NEW.result = 'PASS' AND NOT EXISTS (
    SELECT 1 FROM public.qc_check_items
    WHERE qc_inspection_id = NEW.id AND requirement = 'REQUIRED'
  ) THEN
    RAISE EXCEPTION 'Không thể hoàn tất QC đạt khi thiếu checklist bắt buộc';
  END IF;

  UPDATE public.laptops SET
    charger_status = CASE NEW.charger_status
      WHEN 'MISSING' THEN 'no_charger'
      WHEN 'UNKNOWN' THEN 'unchecked'
      ELSE 'with_charger' END,
    mainboard_status = CASE NEW.mainboard_status
      WHEN 'ORIGINAL' THEN 'ok'
      WHEN 'OFFICIAL_REPLACED' THEN 'ok'
      WHEN 'REPAIRED' THEN 'error'
      ELSE NULL END,
    screen_status = (SELECT CASE result WHEN 'PASS' THEN 'ok'
      WHEN 'FAIL' THEN 'error' WHEN 'WARNING' THEN 'error' ELSE NULL END
      FROM public.qc_check_items WHERE qc_inspection_id = NEW.id AND check_key = 'screen'),
    camera_mic_status = (SELECT CASE
      WHEN bool_or(result IN ('FAIL','WARNING')) THEN 'error'
      WHEN count(*) = 2 AND bool_and(result = 'PASS') THEN 'ok'
      ELSE NULL END FROM public.qc_check_items
      WHERE qc_inspection_id = NEW.id AND check_key IN ('camera','microphone'))
  WHERE id = NEW.laptop_id;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS sync_completed_qc_product ON public.qc_inspections;
CREATE TRIGGER sync_completed_qc_product AFTER UPDATE OF status ON public.qc_inspections
FOR EACH ROW EXECUTE FUNCTION public.sync_completed_qc_product();
REVOKE ALL ON FUNCTION public.sync_completed_qc_product() FROM PUBLIC, anon, authenticated;
NOTIFY pgrst, 'reload schema';


-- MIGRATION: 20260928_quick_qc.sql

ALTER TABLE public.qc_inspections ADD COLUMN IF NOT EXISTS disposition text
  CHECK (disposition IN ('PASS','FAIL','REPAIR','RETURN_CN'));
-- Summary decisions preserve actual measurements; never autofill the checklist.
DROP TRIGGER IF EXISTS sync_completed_qc_product ON public.qc_inspections;
CREATE TRIGGER sync_completed_qc_product AFTER UPDATE OF status ON public.qc_inspections
FOR EACH ROW WHEN (NEW.disposition IS NULL) EXECUTE FUNCTION public.sync_completed_qc_product();

CREATE OR REPLACE FUNCTION public.complete_quick_qc(
  p_inspection_id uuid, p_disposition text, p_notes text, p_actor text, p_idempotency_key text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','pg_temp'
AS $$
DECLARE q qc_inspections%ROWTYPE; l laptops%ROWTYPE; linked jsonb; target text;
BEGIN
  IF coalesce(p_disposition,'') NOT IN ('PASS','FAIL','REPAIR','RETURN_CN')
    OR length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100 THEN
    RAISE EXCEPTION 'Kết quả QC không hợp lệ';
  END IF;
  SELECT * INTO q FROM qc_inspections WHERE id=p_inspection_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiên QC'; END IF;
  IF q.status='COMPLETED' AND q.completion_idempotency_key=p_idempotency_key
    AND q.disposition=p_disposition THEN RETURN to_jsonb(q); END IF;
  IF q.status<>'IN_PROGRESS' THEN RAISE EXCEPTION 'Phiên QC đã kết thúc'; END IF;
  SELECT * INTO l FROM laptops WHERE id=q.laptop_id AND is_active IS TRUE FOR UPDATE;
  IF NOT FOUND OR l.status<>'waiting_qc' THEN RAISE EXCEPTION 'Máy không còn ở trạng thái chờ QC'; END IF;
  IF EXISTS(SELECT 1 FROM repair_jobs WHERE laptop_id=l.id AND status NOT IN ('COMPLETED','CANCELLED'))
    OR EXISTS(SELECT 1 FROM supplier_return_items WHERE laptop_id=l.id AND status NOT IN ('REFUNDED','REPLACED','REJECTED','CANCELLED')) THEN
    RAISE EXCEPTION 'Máy còn phiếu sửa hoặc trả nhà cung cấp đang xử lý';
  END IF;
  IF p_disposition='RETURN_CN' AND (l.purchase_batch_id IS NULL OR l.source_type='UNKNOWN') THEN
    RAISE EXCEPTION 'Cần đối chiếu nhà cung cấp và lô mua trước khi BACK về TQ';
  END IF;
  UPDATE qc_inspections SET status='COMPLETED',
    result=CASE WHEN p_disposition='PASS' THEN 'PASS' ELSE 'FAIL' END,
    disposition=p_disposition, overall_notes=left(coalesce(p_notes,''),5000),
    completed_by=p_actor,completed_at=now(),completion_idempotency_key=p_idempotency_key
  WHERE id=q.id RETURNING * INTO q;
  target:=CASE p_disposition WHEN 'PASS' THEN 'available' WHEN 'REPAIR' THEN 'repair'
    WHEN 'RETURN_CN' THEN 'supplier_return' ELSE 'waiting_qc' END;
  IF p_disposition='REPAIR' THEN
    linked:=start_repair_job(jsonb_build_object('laptop_id',l.id,'source_type','QC','source_id',q.id,
      'reported_issue',coalesce(nullif(btrim(p_notes),''),'QC: Cần sửa chữa')),
      p_actor,'qc-repair-'||q.id::text);
  ELSIF p_disposition='RETURN_CN' THEN
    linked:=create_supplier_return(jsonb_build_object('reason','OTHER','reason_notes',coalesce(p_notes,'')),
      jsonb_build_array(jsonb_build_object('laptop_id',l.id,'qc_inspection_id',q.id,
        'reason','OTHER','condition_notes',coalesce(p_notes,''))),p_actor,'qc-return-'||q.id::text);
  ELSE
    PERFORM set_config('app.laptop_transition','on',true);
    UPDATE laptops SET status=target,
      available_for_sale_at=CASE WHEN p_disposition='PASS' THEN now() ELSE NULL END
    WHERE id=l.id;
  END IF;
  INSERT INTO stock_movements(laptop_id,movement_type,reference_type,reference_id,note,performed_by)
  VALUES(l.id,'QC_'||p_disposition,'QC_INSPECTION',q.id::text,coalesce(p_notes,''),p_actor);
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('QC_INSPECTION',q.id::text,'UPDATE',jsonb_build_object('disposition',p_disposition,
    'laptop_id',l.id,'status',target,'linked_record',linked),p_actor);
  RETURN to_jsonb(q);
END;
$$;
REVOKE ALL ON FUNCTION public.complete_quick_qc(uuid,text,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.complete_quick_qc(uuid,text,text,text,text) TO service_role;
NOTIFY pgrst,'reload schema';


-- MIGRATION: 20260929_purchase_import_price.sql
-- Persist the VND import price entered or calculated in the purchase-batch UI.

CREATE OR REPLACE FUNCTION public.create_purchase_batch(
  p_batch jsonb, p_laptops jsonb, p_actor text, p_idempotency_key text
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','pg_temp'
AS $$
DECLARE
  b purchase_batches%ROWTYPE;
  entry jsonb;
  created_rows jsonb;
  rate numeric;
  extra_vnd numeric;
  divisor numeric;
  import_price numeric;
BEGIN
  SELECT result INTO created_rows FROM operation_requests
  WHERE idempotency_key=p_idempotency_key AND operation='CREATE_PURCHASE_BATCH';
  IF FOUND THEN RETURN created_rows; END IF;

  IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100
     OR jsonb_typeof(p_laptops) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_laptops) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'LÃ´ mua pháº£i cÃ³ tá»« 1 Ä‘áº¿n 200 mÃ¡y';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM suppliers
    WHERE id=(p_batch->>'supplier_id')::uuid AND active
  ) THEN
    RAISE EXCEPTION 'NhÃ  cung cáº¥p khÃ´ng tá»“n táº¡i hoáº·c Ä‘Ã£ ngá»«ng sá»­ dá»¥ng';
  END IF;

  rate:=coalesce(nullif(p_batch->>'purchase_exchange_rate','')::numeric,
                 nullif(p_batch->>'exchange_rate','')::numeric);
  IF rate IS NULL OR rate<=0 THEN RAISE EXCEPTION 'Tá»· giÃ¡ mua khÃ´ng há»£p lá»‡'; END IF;
  SELECT coalesce(nullif(value->>'shippingVnd','')::numeric,400000),
         coalesce(nullif(value->>'divisor','')::numeric,1000000)
    INTO extra_vnd,divisor FROM app_settings WHERE key='formula';
  extra_vnd:=coalesce(extra_vnd,400000);
  divisor:=coalesce(divisor,1000000);

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_laptops) x WHERE
      length(btrim(coalesce(x->>'name',''))) NOT BETWEEN 1 AND 240
      OR NOT EXISTS (
        SELECT 1 FROM app_options o
        WHERE o.group_key='category' AND o.option_key=x->>'category' AND o.is_active IS TRUE
      )
      OR coalesce(nullif(x->>'purchase_price_rmb','')::numeric,-1)<0
      OR coalesce(nullif(x->>'shipping_rmb','')::numeric,0)<0
      OR coalesce(nullif(x->>'import_price_vnd','')::numeric,-1)<0
      OR length(coalesce(x->>'tracking_code_cn',''))>200
  ) THEN
    RAISE EXCEPTION 'ThÃ´ng tin mÃ¡y trong lÃ´ khÃ´ng há»£p lá»‡';
  END IF;

  INSERT INTO purchase_batches(batch_code,supplier_id,purchase_date,currency,exchange_rate,
    subtotal_rmb,domestic_shipping_rmb,other_cost_rmb,destination,status,notes,active,
    created_by,updated_by,idempotency_key,procurement_flow)
  VALUES(next_purchase_batch_code((p_batch->>'purchase_date')::date),
    (p_batch->>'supplier_id')::uuid,(p_batch->>'purchase_date')::date,'CNY',rate,
    0,0,0,'OTHER','CONFIRMED',left(coalesce(p_batch->>'notes',''),3000),true,
    p_actor,p_actor,p_idempotency_key,'DIRECT')
  RETURNING * INTO b;

  FOR entry IN SELECT value FROM jsonb_array_elements(p_laptops) LOOP
    import_price:=coalesce(
      nullif(entry->>'import_price_vnd','')::numeric,
      round((
        (entry->>'purchase_price_rmb')::numeric
        + coalesce(nullif(entry->>'shipping_rmb','')::numeric,0)
      ) * rate + extra_vnd,2) / divisor
    );
    INSERT INTO laptops(name,category,serial,tracking_code_cn,purchase_price_rmb,shipping_rmb,
      purchase_exchange_rate,import_price_vnd,purchase_batch_id,source_type,status,location,
      charger_status,is_active,condition_note,created_by,import_date,month_key,price_rmb,
      exchange_rate,tracking_code)
    VALUES(btrim(entry->>'name'),entry->>'category',
      nullif(left(btrim(coalesce(entry->>'serial','')),100),''),
      left(btrim(coalesce(entry->>'tracking_code_cn','')),200),
      (entry->>'purchase_price_rmb')::numeric,
      coalesce(nullif(entry->>'shipping_rmb','')::numeric,0),rate,import_price,b.id,
      'SUPPLIER_PURCHASE','in_transit','wh_cn','unchecked',true,
      left(coalesce(entry->>'notes',''),2000),p_actor,b.purchase_date,
      to_char(b.purchase_date,'MM/YYYY'),(entry->>'purchase_price_rmb')::numeric,rate,
      left(btrim(coalesce(entry->>'tracking_code_cn','')),200));
  END LOOP;

  SELECT jsonb_build_object('batch',to_jsonb(b),
    'laptops',coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb))
  INTO created_rows FROM laptops l WHERE l.purchase_batch_id=b.id;
  INSERT INTO operation_requests(idempotency_key,operation,result,created_by)
  VALUES(p_idempotency_key,'CREATE_PURCHASE_BATCH',created_rows,p_actor);
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('PURCHASE_BATCH',b.id::text,'CREATE',
    jsonb_build_object('batch_code',b.batch_code,'laptop_count',jsonb_array_length(p_laptops)),p_actor);
  RETURN created_rows;
END;
$$;
